["Af belgesi alınıyor"] = "AF BELGESİ ALINIYOR",
["Aferin Dallas. Minibüse gidip çık oradan."] = "AFERİN DALLAS. MİNİBÜSE GİDİP ÇIK ORADAN.",
["Aferin Dallas. Sende hâlâ iş var. Şimdi ganimeti minibüse at da gidelim."] = "AFERİN DALLAS. SENDE HÂLÂ İŞ VAR. ŞİMDİ GANİMETİ MİNİBÜSE AT DA GİDELİM.",
["Aferin dostlar!"] = "AFERİN DOSTLAR!",
["Aferin dostlar, kolay ve hızlı para kazandık. Gelecekte daha çok iş başarmak için kullanabileceğimiz bir sürü güzel şey alacağız, ha?"] = "AFERİN DOSTLAR, KOLAY VE HIZLI PARA KAZANDIK. GELECEKTE DAHA ÇOK İŞ BAŞARMAK İÇİN KULLANABİLECEĞİMİZ BİR SÜRÜ GÜZEL ŞEY ALACAĞIZ, HA?",
["Aferin dostlar."] = "AFERİN DOSTLAR.",
["Aferin dostlar. "] = "AFERİN DOSTLAR. ",
["Aferin dostlar. Aradığımız şey bu."] = "AFERİN DOSTLAR. ARADIĞIMIZ ŞEY BU.",
["Aferin dostlar. Emniyet Müdürü Garrett'ın ayağının altından halıyı çektik. Önündeki birkaç saatin pek hoş geçmeyeceğini tahmin ediyorum. Toplantıya eli boş gittiğinde orada olmak vardı, ha? Bain gurur duyardı. Güvenli eve döner dönmez Duke, Elephant'ın kutusunu incelemeye başlamalı. Las Vegas'ta aldığınız kutuyla, Bain'in kâse zımbırtısıyla ve şu Kataru hödükleriyle bağlantısını öğrenmeliyiz. Sonra sıradaki hamlemizi planlarız."] = "AFERİN DOSTLAR. EMNİYET MÜDÜRÜ GARRETT'IN AYAĞININ ALTINDAN HALIYI ÇEKTİK. ÖNÜNDEKİ BİRKAÇ SAATİN PEK HOŞ GEÇMEYECEĞİNİ TAHMİN EDİYORUM. TOPLANTIYA ELİ BOŞ GİTTİĞİNDE ORADA OLMAK VARDI, HA? BAIN GURUR DUYARDI. GÜVENLİ EVE DÖNER DÖNMEZ DUKE, ELEPHANT'IN KUTUSUNU İNCELEMEYE BAŞLAMALI. LAS VEGAS'TA ALDIĞINIZ KUTUYLA, BAIN'İN KÂSE ZIMBIRTISIYLA VE ŞU KATARU HÖDÜKLERİYLE BAĞLANTISINI ÖĞRENMELİYİZ. SONRA SIRADAKİ HAMLEMİZİ PLANLARIZ.",
["Aferin dostlar. Geriye çelik halatla sıvışmak kaldı."] = "AFERİN DOSTLAR. GERİYE ÇELİK HALATLA SIVIŞMAK KALDI.",
["Aferin dostlar. Şimdi gidip o kapıyı açabilirsiniz."] = "AFERİN DOSTLAR. ŞİMDİ GİDİP O KAPIYI AÇABİLİRSİNİZ.",
["Aferin dostlar. Şimdi kasa dairesine ulaşmadan önce aşmanız gereken bir güvenlik kapısı var."] = "AFERİN DOSTLAR. ŞİMDİ KASA DAİRESİNE ULAŞMADAN ÖNCE AŞMANIZ GEREKEN BİR GÜVENLİK KAPISI VAR.",
["Aferin dostlarım! O Murky piçlerinin bunu nasıl açıklayacağını görmek için sabırsızlanıyorum."] = "AFERİN DOSTLARIM! O MURKY PİÇLERİNİN BUNU NASIL AÇIKLAYACAĞINI GÖRMEK İÇİN SABIRSIZLANIYORUM.",
["Aferin ekip, metal dedektörleri devre dışı."] = "AFERİN EKİP, METAL DEDEKTÖRLERİ DEVRE DIŞI.",
["Aferin hödükler! Yufu Wang ve Golden Dagger, Payday Gang'in adını duydukları güne lanet ediyor. Onları kesin yıkımın eşiğine getirdik! "] = "AFERİN HÖDÜKLER! YUFU WANG VE GOLDEN DAGGER, PAYDAY GANG'İN ADINI DUYDUKLARI GÜNE LANET EDİYOR. ONLARI KESİN YIKIMIN EŞİĞİNE GETİRDİK! ",
["Aferin millet."] = "AFERİN MİLLET.",
["Aferin millet. Keskin nişancılar gidince Bile yükü bırakabilir."] = "AFERİN MİLLET. KESKİN NİŞANCILAR GİDİNCE BILE YÜKÜ BIRAKABİLİR.",
["Aferin millet. Sunucu güvene alındı, Jimmy memnun olacak."] = "AFERİN MİLLET. SUNUCU GÜVENE ALINDI, JIMMY MEMNUN OLACAK.",
["Aferin millet. The Elephant memnun olacak, kimse bir şeyden şüphelenmiyor."] = "AFERİN MİLLET. THE ELEPHANT MEMNUN OLACAK, KİMSE BİR ŞEYDEN ŞÜPHELENMİYOR.",
["Aferin millet. Şimdi kırmızı çıkartmalı tabloları arıyorsunuz. Demokratın istedikleri onlar. En az dört tane alın. "] = "AFERİN MİLLET. ŞİMDİ KIRMIZI ÇIKARTMALI TABLOLARI ARIYORSUNUZ. DEMOKRATIN İSTEDİKLERİ ONLAR. EN AZ DÖRT TANE ALIN. ",
["Aferin soyguncu! İşte böyle beslenir o Kumbara!"] = "AFERİN SOYGUNCU! İŞTE BÖYLE BESLENİR O KUMBARA!",
["Aferin!"] = "AFERİN!",
["Aferin! Beşinci dalga geri püskürtüldü!"] = "AFERİN! BEŞİNCİ DALGA GERİ PÜSKÜRTÜLDÜ!",
["Aferin! Hazır olunca cam temizleme platformundan çıkın. Kutlama vakti!"] = "AFERİN! HAZIR OLUNCA CAM TEMİZLEME PLATFORMUNDAN ÇIKIN. KUTLAMA VAKTİ!",
["Aferin! O sunucu odasını bulalım. Gizli bir girişin arkasında olmalıymış. Wang sinsi biridir, birkaç çıkmaz yola hazır olun."] = "AFERİN! O SUNUCU ODASINI BULALIM. GİZLİ BİR GİRİŞİN ARKASINDA OLMALIYMIŞ. WANG SİNSİ BİRİDİR, BİRKAÇ ÇIKMAZ YOLA HAZIR OLUN.",
["Aferin! Pişirmeye dönün. Dalgalar arasındaki süreyi daha fazla malzeme bulmak için kullanın."] = "AFERİN! PİŞİRMEYE DÖNÜN. DALGALAR ARASINDAKİ SÜREYİ DAHA FAZLA MALZEME BULMAK İÇİN KULLANIN.",
["Aferin! Sekizinci dalga geri püskürtüldü!"] = "AFERİN! SEKİZİNCİ DALGA GERİ PÜSKÜRTÜLDÜ!",
["Aferin! Şoförümüz silahları almaya geliyor."] = "AFERİN! ŞOFÖRÜMÜZ SİLAHLARI ALMAYA GELİYOR.",
["Aferin, hemen ilgileniyorum."] = "AFERİN, HEMEN İLGİLENİYORUM.",
["Aferin, ikinci rakam da bulundu. Bir tane kaldı."] = "AFERİN, İKİNCİ RAKAM DA BULUNDU. BİR TANE KALDI.",
["Aferin, sabit disk elimizde! Wang'ı alma vakti. Piç toplantı odasına saklanmış. Sergi arabasının platformunu çevirin, kapıyı onunla kıracağız."] = "AFERİN, SABİT DİSK ELİMİZDE! WANG'I ALMA VAKTİ. PİÇ TOPLANTI ODASINA SAKLANMIŞ. SERGİ ARABASININ PLATFORMUNU ÇEVİRİN, KAPIYI ONUNLA KIRACAĞIZ.",
["Aferin, sıçan öldü, kaçış helikopteri bekliyor. Otobüsteki parayı almak istemiyorsanız helikoptere gidin de sizi oradan çıkaralım."] = "AFERİN, SIÇAN ÖLDÜ, KAÇIŞ HELİKOPTERİ BEKLİYOR. OTOBÜSTEKİ PARAYI ALMAK İSTEMİYORSANIZ HELİKOPTERE GİDİN DE SİZİ ORADAN ÇIKARALIM.",
["Aferin, çıktık buradan."] = "AFERİN, ÇIKTIK BURADAN.",
["Aferin, şimdi diğerine gidin."] = "AFERİN, ŞİMDİ DİĞERİNE GİDİN.",
["Aferin, şimdi diğerini kesin."] = "AFERİN, ŞİMDİ DİĞERİNİ KESİN.",
["Aferin. Bir Anahtar Kartı daha bulmak kaldı."] = "AFERİN. BİR ANAHTAR KARTI DAHA BULMAK KALDI.",
["Aferin. Dört çanta gidip takas yapmak için yeterli."] = "AFERİN. DÖRT ÇANTA GİDİP TAKAS YAPMAK İÇİN YETERLİ.",
["Aferin. Helikoptere binin de paramızı alalım."] = "AFERİN. HELİKOPTERE BİNİN DE PARAMIZI ALALIM.",
["Aferin. Parayı o kafesle çıkaracağız. Doldurmaya başlayın."] = "AFERİN. PARAYI O KAFESLE ÇIKARACAĞIZ. DOLDURMAYA BAŞLAYIN.",
["Aferin. Sırada o patlayıcılara fünye takmak var. Ayarlayın, olur mu?"] = "AFERİN. SIRADA O PATLAYICILARA FÜNYE TAKMAK VAR. AYARLAYIN, OLUR MU?",
["Aferin. Şimdi içeri ilerleyin."] = "AFERİN. ŞİMDİ İÇERİ İLERLEYİN.",
["Aferin. Şimdi kapılara C4!"] = "AFERİN. ŞİMDİ KAPILARA C4!",
["Aferin. Şimdi o ofise girin dostlar."] = "AFERİN. ŞİMDİ O OFİSE GİRİN DOSTLAR.",
["Affedenlerden Değilim"] = "AFFEDENLERDEN DEĞİLİM",
["Affedersiniz, Domuz Etimde Mermi Var..."] = "AFFEDERSİNİZ, DOMUZ ETİMDE MERMİ VAR...",
["Affet ama asla unutma."] = "AFFET AMA ASLA UNUTMA.",
["Afrika'dan nadir etlerden oluşan nefis bir seçkimiz var. Hiç fil eti tattınız mı?"] = "AFRİKA'DAN NADİR ETLERDEN OLUŞAN NEFİS BİR SEÇKİMİZ VAR. HİÇ FİL ETİ TATTINIZ MI?",
["Afrikaanca mı konuştum? Kusura bakmayın! Demek istediğim, ‘lütfen’ ‘patlayıcıları’ ‘kilitlerin’ ‘üzerine’ ‘yerleştirin’... sizi boklar."] = "AFRİKAANCA MI KONUŞTUM? KUSURA BAKMAYIN! DEMEK İSTEDİĞİM, ‘LÜTFEN’ ‘PATLAYICILARI’ ‘KİLİTLERİN’ ‘ÜZERİNE’ ‘YERLEŞTİRİN’... SİZİ BOKLAR.",
["Aftershock soygununda evsizin bıçağını bul."] = "AFTERSHOCK SOYGUNUNDA EVSİZİN BIÇAĞINI BUL.",
["Aftershock soygununu Death Sentence zorlukta One Down kuralı etkinken tamamla."] = "AFTERSHOCK SOYGUNUNU DEATH SENTENCE ZORLUKTA ONE DOWN KURALI ETKİNKEN TAMAMLA.",
["Aftershock soygununu Death Sentence zorlukta tamamla."] = "AFTERSHOCK SOYGUNUNU DEATH SENTENCE ZORLUKTA TAMAMLA.",
["Aftershock soygununu Death Wish veya daha yüksek zorlukta tamamla."] = "AFTERSHOCK SOYGUNUNU DEATH WISH VEYA DAHA YÜKSEK ZORLUKTA TAMAMLA.",
["Aftershock soygununu Mayhem veya daha yüksek zorlukta tamamla."] = "AFTERSHOCK SOYGUNUNU MAYHEM VEYA DAHA YÜKSEK ZORLUKTA TAMAMLA.",
["Aftershock soygununu Normal veya daha yüksek zorlukta tamamla."] = "AFTERSHOCK SOYGUNUNU NORMAL VEYA DAHA YÜKSEK ZORLUKTA TAMAMLA.",
["Aftershock soygununu OVERKILL veya daha yüksek zorlukta tamamla."] = "AFTERSHOCK SOYGUNUNU OVERKILL VEYA DAHA YÜKSEK ZORLUKTA TAMAMLA.",
["Aftershock soygununu Zor veya daha yüksek zorlukta tamamla."] = "AFTERSHOCK SOYGUNUNU ZOR VEYA DAHA YÜKSEK ZORLUKTA TAMAMLA.",
["Aftershock soygununu Çok Zor veya daha yüksek zorlukta tamamla."] = "AFTERSHOCK SOYGUNUNU ÇOK ZOR VEYA DAHA YÜKSEK ZORLUKTA TAMAMLA.",
["Ah be, neredeyse hepsi gitti. Hepsi! Lütfen, en azından birazını almaya çalışın!"] = "AH BE, NEREDEYSE HEPSİ GİTTİ. HEPSİ! LÜTFEN, EN AZINDAN BİRAZINI ALMAYA ÇALIŞIN!",
["Ah be, yanlış koddu!"] = "AH BE, YANLIŞ KODDU!",
["Ah dostlarım. Belki bir dahaki sefer doğru yaparız, ha?"] = "AH DOSTLARIM. BELKİ BİR DAHAKİ SEFER DOĞRU YAPARIZ, HA?",
["Ah dostlarım. Şu 'katırlar' var ya... aslında keçiler. Ve... ee, kaçmışlar. Benim için bulun onları."] = "AH DOSTLARIM. ŞU 'KATIRLAR' VAR YA... ASLINDA KEÇİLER. VE... EE, KAÇMIŞLAR. BENİM İÇİN BULUN ONLARI.",
["Ah dostum! O kapıları biraz güç kullanmadan açamazsınız. Ama merak etmeyin, Locke'un planı var. Önce asansöre yeniden elektrik vermelisiniz. Jeneratörü bulup çalıştırın."] = "AH DOSTUM! O KAPILARI BİRAZ GÜÇ KULLANMADAN AÇAMAZSINIZ. AMA MERAK ETMEYİN, LOCKE'UN PLANI VAR. ÖNCE ASANSÖRE YENİDEN ELEKTRİK VERMELİSİNİZ. JENERATÖRÜ BULUP ÇALIŞTIRIN.",
["Ah dostum, bu pek hoş değildi!"] = "AH DOSTUM, BU PEK HOŞ DEĞİLDİ!",
["Ah dostum, içeride müthiş konser var gibi."] = "AH DOSTUM, İÇERİDE MÜTHİŞ KONSER VAR GİBİ.",
["Ah dostum, pilot yine düştü. O ihtiyar şarapçıyı uyandırın!"] = "AH DOSTUM, PİLOT YİNE DÜŞTÜ. O İHTİYAR ŞARAPÇIYI UYANDIRIN!",
["Ah dostum, polisler çıldırıyor! İşleri biraz daha kızıştırmak üzereler!"] = "AH DOSTUM, POLİSLER ÇILDIRIYOR! İŞLERİ BİRAZ DAHA KIZIŞTIRMAK ÜZERELER!",
["Ah dostum... Kesin öldüm sanıyordum... Bir grup palyaçonun gelip kıçımı kurtarmasını beklediğimi söyleyemem."] = "AH DOSTUM... KESİN ÖLDÜM SANIYORDUM... BİR GRUP PALYAÇONUN GELİP KIÇIMI KURTARMASINI BEKLEDİĞİMİ SÖYLEYEMEM.",
["Ah evet! Yakaladım o piçi!"] = "AH EVET! YAKALADIM O PİÇİ!",
["Ah evet, polislerden çalmak. En sevdiğimiz tatil geleneği!"] = "AH EVET, POLİSLERDEN ÇALMAK. EN SEVDİĞİMİZ TATİL GELENEĞİ!",
["Ah evet. Çağrı cihazları."] = "AH EVET. ÇAĞRI CİHAZLARI.",
["Ah güzel, RFID kutusu. Onları severiz. Kasa dairesini açmak için devre atlatma işlemini yapın."] = "AH GÜZEL, RFID KUTUSU. ONLARI SEVERİZ. KASA DAİRESİNİ AÇMAK İÇİN DEVRE ATLATMA İŞLEMİNİ YAPIN.",
["Ah güzel. Butcher yardım yolladı. Şimdi bağlarımı çözün lütfen."] = "AH GÜZEL. BUTCHER YARDIM YOLLADI. ŞİMDİ BAĞLARIMI ÇÖZÜN LÜTFEN.",
["Ah hayır! Metal dedektörü yeni!"] = "AH HAYIR! METAL DEDEKTÖRÜ YENİ!",
["Ah hayır! Patladı, dikkat edin! O ateşten uzak durun!"] = "AH HAYIR! PATLADI, DİKKAT EDİN! O ATEŞTEN UZAK DURUN!",
["Ah hayır! Sistem kırma cihazını görüp haber verdiler. B planı millet!"] = "AH HAYIR! SİSTEM KIRMA CİHAZINI GÖRÜP HABER VERDİLER. B PLANI MİLLET!",
["Ah hayır, BENİ kandırmaya çalışmıyorsun, değil mi?"] = "AH HAYIR, BENİ KANDIRMAYA ÇALIŞMIYORSUN, DEĞİL Mİ?",
["Ah hayır, beni kandırmaya çalışmıyorsunuz, değil mi?"] = "AH HAYIR, BENİ KANDIRMAYA ÇALIŞMIYORSUNUZ, DEĞİL Mİ?",
["Ah hayır, daha fazla keskin nişancı!"] = "AH HAYIR, DAHA FAZLA KESKİN NİŞANCI!",
["Ah hayır, o değil!"] = "AH HAYIR, O DEĞİL!",
["Ah hayır... şimdi kesin yarına kadar buradayız."] = "AH HAYIR... ŞİMDİ KESİN YARINA KADAR BURADAYIZ.",
["Ah kahretsin, hedefi 20 metre kaçırdım. Kusura bakmayın yoldaşlar."] = "AH KAHRETSİN, HEDEFİ 20 METRE KAÇIRDIM. KUSURA BAKMAYIN YOLDAŞLAR.",
["Ah lanet olsun Pedro, yine ucuz konserve et kullandın, değil mi?"] = "AH LANET OLSUN PEDRO, YİNE UCUZ KONSERVE ET KULLANDIN, DEĞİL Mİ?",
["Ah lanet olsun!"] = "AH LANET OLSUN!",
["Ah lanet olsun. Yanlış bilgisayar. Alarmlar tetiklendi. Polis yolda. Fazla vaktimiz kalmadı."] = "AH LANET OLSUN. YANLIŞ BİLGİSAYAR. ALARMLAR TETİKLENDİ. POLİS YOLDA. FAZLA VAKTİMİZ KALMADI.",
["Ah lanet. Polisler yolda. Mekânı gözetliyorlarmış galiba."] = "AH LANET. POLİSLER YOLDA. MEKÂNI GÖZETLİYORLARMIŞ GALİBA.",
["Ah lanet... Çatıyı ıskaladım... Millet, C4 arka sokağa düştü..."] = "AH LANET... ÇATIYI ISKALADIM... MİLLET, C4 ARKA SOKAĞA DÜŞTÜ...",
["Ah millet... Umarım servis ücretsizdir. "] = "AH MİLLET... UMARIM SERVİS ÜCRETSİZDİR. ",
["Ah siktiiiiir!"] = "AH SİKTİİİİİR!",
["Ah siktiiiir!"] = "AH SİKTİİİİR!",
["Ah siktir!"] = "AH SİKTİR!",
["Ah siktir! Alarm tetiklenince güvenlik sistemi konteynerleri kilitlemiş. Görünüşe göre deleceğiz."] = "AH SİKTİR! ALARM TETİKLENİNCE GÜVENLİK SİSTEMİ KONTEYNERLERİ KİLİTLEMİŞ. GÖRÜNÜŞE GÖRE DELECEĞİZ.",
["Ah siktir! Anlaşmamız bu değildi! Gidiyoruz biz!"] = "AH SİKTİR! ANLAŞMAMIZ BU DEĞİLDİ! GİDİYORUZ BİZ!",
["Ah siktir! Sistem kilitliyken o tuş takımı çalışmaz. Kapıyı bir şekilde zorla açmanız gerekecek."] = "AH SİKTİR! SİSTEM KİLİTLİYKEN O TUŞ TAKIMI ÇALIŞMAZ. KAPIYI BİR ŞEKİLDE ZORLA AÇMANIZ GEREKECEK.",
["Ah siktir! Zaman kilidi devrede. Anahtar kartlarını unutun. O panelleri zorlayın."] = "AH SİKTİR! ZAMAN KİLİDİ DEVREDE. ANAHTAR KARTLARINI UNUTUN. O PANELLERİ ZORLAYIN.",
["Ah siktir, acil çıkış yerine çatıya kaçmış. Yukarı çıkıp indirin onu."] = "AH SİKTİR, ACİL ÇIKIŞ YERİNE ÇATIYA KAÇMIŞ. YUKARI ÇIKIP İNDİRİN ONU.",
["Ah siktir, arabayı çekmem lazım!"] = "AH SİKTİR, ARABAYI ÇEKMEM LAZIM!",
["Ah siktir, bu yere düşünce kırılmış. Para desteleri her yana saçıldı. Bulup çantalamalı, buraya geri getirmelisiniz."] = "AH SİKTİR, BU YERE DÜŞÜNCE KIRILMIŞ. PARA DESTELERİ HER YANA SAÇILDI. BULUP ÇANTALAMALI, BURAYA GERİ GETİRMELİSİNİZ.",
["Ah siktir, bunu hesaba katmamıştım. Hiçbir şey kolay olmaz zaten."] = "AH SİKTİR, BUNU HESABA KATMAMIŞTIM. HİÇBİR ŞEY KOLAY OLMAZ ZATEN.",
["Ah siktir, işte oldu... B planı!"] = "AH SİKTİR, İŞTE OLDU... B PLANI!",
["Ah siktir, o amcıklar sırf beni düşürmek için daha fazla SWAT tareti getiriyor. Tamam, sizi şehirden alamam ama buna hazırlıklıyım."] = "AH SİKTİR, O AMCIKLAR SIRF BENİ DÜŞÜRMEK İÇİN DAHA FAZLA SWAT TARETİ GETİRİYOR. TAMAM, SİZİ ŞEHİRDEN ALAMAM AMA BUNA HAZIRLIKLIYIM.",
["Ah siktir, o bir saldırı helikopteri mi?"] = "AH SİKTİR, O BİR SALDIRI HELİKOPTERİ Mİ?",
["Ah siktir, polis geldi! Hadi çıkalım buradan! "] = "AH SİKTİR, POLİS GELDİ! HADİ ÇIKALIM BURADAN! ",
["Ah siktir, polis köprünün dönüşünü durdurdu. Yeniden başlatmak gerek. Biriniz ilgilensin!"] = "AH SİKTİR, POLİS KÖPRÜNÜN DÖNÜŞÜNÜ DURDURDU. YENİDEN BAŞLATMAK GEREK. BİRİNİZ İLGİLENSİN!",
["Ah siktir, siktir, bir şey unuttum. Dinleyin, kaset bulursanız onları da alın lütfen... Ne bileyim, belki sonra bir yerde yakarsınız, olur mu?"] = "AH SİKTİR, SİKTİR, BİR ŞEY UNUTTUM. DİNLEYİN, KASET BULURSANIZ ONLARI DA ALIN LÜTFEN... NE BİLEYİM, BELKİ SONRA BİR YERDE YAKARSINIZ, OLUR MU?",
["Ah siktir, tüymeye çalıştığımızı biliyorlar. Her şeyleriyle geliyorlar! Sağlam durun dostlarım!"] = "AH SİKTİR, TÜYMEYE ÇALIŞTIĞIMIZI BİLİYORLAR. HER ŞEYLERİYLE GELİYORLAR! SAĞLAM DURUN DOSTLARIM!",
["Ah siktir. Silahların bazıları parça hâlinde. Yanlışlıkla parça bırakırsak pek para etmezler. Bence kendimizi garantiye almak için silah atölyesini kullanalım."] = "AH SİKTİR. SİLAHLARIN BAZILARI PARÇA HÂLİNDE. YANLIŞLIKLA PARÇA BIRAKIRSAK PEK PARA ETMEZLER. BENCE KENDİMİZİ GARANTİYE ALMAK İÇİN SİLAH ATÖLYESİNİ KULLANALIM.",
["Ah siktir. Sunucunun her yanı şifreli. Şifre anahtarları Güvenlik Ofisinde olmalı. Oraya gidin, alın ve buraya getirin."] = "AH SİKTİR. SUNUCUNUN HER YANI ŞİFRELİ. ŞİFRE ANAHTARLARI GÜVENLİK OFİSİNDE OLMALI. ORAYA GİDİN, ALIN VE BURAYA GETİRİN.",
["Ah siktir. Uçağın inmesi gerek. Tamam, plan değiştiriyoruz."] = "AH SİKTİR. UÇAĞIN İNMESİ GEREK. TAMAM, PLAN DEĞİŞTİRİYORUZ.",
["Ah siktir. Yine ofisinde. Onu oradan çıkarmalıyız."] = "AH SİKTİR. YİNE OFİSİNDE. ONU ORADAN ÇIKARMALIYIZ.",
["Ah tamam... Görünüşe göre burada biraz fazla var. Füzyon motoru yani. Doğru olanı bulun."] = "AH TAMAM... GÖRÜNÜŞE GÖRE BURADA BİRAZ FAZLA VAR. FÜZYON MOTORU YANİ. DOĞRU OLANI BULUN.",
["Ah yahu, pompa durdu. Belki biraz daha enerji lazımdır?"] = "AH YAHU, POMPA DURDU. BELKİ BİRAZ DAHA ENERJİ LAZIMDIR?",
["Ah şu lanet lobi! Çıkmalısınız oradan!"] = "AH ŞU LANET LOBİ! ÇIKMALISINIZ ORADAN!",
["Ah! Acil kapatma noktasından elektriği kestiler. Şarja devam etmek için kolu bulup geri çekin."] = "AH! ACİL KAPATMA NOKTASINDAN ELEKTRİĞİ KESTİLER. ŞARJA DEVAM ETMEK İÇİN KOLU BULUP GERİ ÇEKİN.",
["Ah! Aptal. Tamam... Wuh duh ma huh tah duh fong kwong duh wai shung!"] = "AH! APTAL. TAMAM... WUH DUH MA HUH TAH DUH FONG KWONG DUH WAİ SHUNG!",
["Ah! Artık filikalarla asla kaçamazsınız. Çok yavaşlar. Helikopter pistine çıkın, biraz yakıt bulup işaret ateşi yakın. Her ihtimale karşı bir helikopter hazır bekletiyordum."] = "AH! ARTIK FİLİKALARLA ASLA KAÇAMAZSINIZ. ÇOK YAVAŞLAR. HELİKOPTER PİSTİNE ÇIKIN, BİRAZ YAKIT BULUP İŞARET ATEŞİ YAKIN. HER İHTİMALE KARŞI BİR HELİKOPTER HAZIR BEKLETİYORDUM.",
["Ah! Başardınız mı dostlarım?"] = "AH! BAŞARDINIZ MI DOSTLARIM?",
["Ah! Beyler! Selamlar!"] = "AH! BEYLER! SELAMLAR!",
["Ah! Binayı aramaya başladılar!"] = "AH! BİNAYI ARAMAYA BAŞLADILAR!",
["Ah! Bir amcık bu kuşla gezintiye çıkmış. Yakıt boş. İyi bir çocuk olup yakıt hattını bağlar mısınız?"] = "AH! BİR AMCIK BU KUŞLA GEZİNTİYE ÇIKMIŞ. YAKIT BOŞ. İYİ BİR ÇOCUK OLUP YAKIT HATTINI BAĞLAR MISINIZ?",
["Ah! Bir güvenlik protokolünü tetikledim. Beni erişim noktasına bağlayın!"] = "AH! BİR GÜVENLİK PROTOKOLÜNÜ TETİKLEDİM. BENİ ERİŞİM NOKTASINA BAĞLAYIN!",
["Ah! Biri pompayı durdurdu. Yeniden çalıştırın!"] = "AH! BİRİ POMPAYI DURDURDU. YENİDEN ÇALIŞTIRIN!",
["Ah! Bu bir Franz Jäger Mark II."] = "AH! BU BİR FRANZ JÄGER MARK II.",
["Ah! Burada güzel konserler oldu. Alesso'nunki şimdiye kadarkilerin en büyüğü."] = "AH! BURADA GÜZEL KONSERLER OLDU. ALESSO'NUNKİ ŞİMDİYE KADARKİLERİN EN BÜYÜĞÜ.",
["Ah! Demek Winston sizi aradı. Burada bana yardım edebilir misiniz?"] = "AH! DEMEK WİNSTON SİZİ ARADI. BURADA BANA YARDIM EDEBİLİR MİSİNİZ?",
["Ah! Dostlarım! Black Ridge'e hoş geldiniz. Burası şey için kullanılıyor, şimdilik çok değerli ganimet tutuyor. Çalalım!"] = "AH! DOSTLARIM! BLACK RİDGE'E HOŞ GELDİNİZ. BURASI ŞEY İÇİN KULLANILIYOR, ŞİMDİLİK ÇOK DEĞERLİ GANİMET TUTUYOR. ÇALALIM!",
["Ah! Elektriği kestiler! Tekrar açın, olur mu?"] = "AH! ELEKTRİĞİ KESTİLER! TEKRAR AÇIN, OLUR MU?",
["Ah! Evet, görüyorum. Geliyorum. Paletleri helikoptere bağlamaya hazır olun. Mümkünse hızlı yapın. Ortalık sıcak."] = "AH! EVET, GÖRÜYORUM. GELİYORUM. PALETLERİ HELİKOPTERE BAĞLAMAYA HAZIR OLUN. MÜMKÜNSE HIZLI YAPIN. ORTALIK SICAK.",
["Ah! Evet, sanırım o merdiven işimize yarayacak!"] = "AH! EVET, SANIRIM O MERDİVEN İŞİMİZE YARAYACAK!",
["Ah! Evet. Kasa Dairesi tekrar açılıyor! Güzel!"] = "AH! EVET. KASA DAİRESİ TEKRAR AÇILIYOR! GÜZEL!",
["Ah! Federaller duvarları yıkıp giriyor!"] = "AH! FEDERALLER DUVARLARI YIKIP GİRİYOR!",
["Ah! Gaz salıyorlar! Ya geçmesini bekleyecek bir yer bulun ya da kapatın!"] = "AH! GAZ SALIYORLAR! YA GEÇMESİNİ BEKLEYECEK BİR YER BULUN YA DA KAPATIN!",
["Ah! Hayır! Hayır!"] = "AH! HAYIR! HAYIR!",
["Ah! Hayır, bu doğru değildi..."] = "AH! HAYIR, BU DOĞRU DEĞİLDİ...",
["Ah! Herifler burada da varsa Garrett Murky'ye yardım işini büyütmüş olmalı. Ta buralara gelmiş. Ya da bize çok kızgın."] = "AH! HERİFLER BURADA DA VARSA GARRETT MURKY'YE YARDIM İŞİNİ BÜYÜTMÜŞ OLMALI. TA BURALARA GELMİŞ. YA DA BİZE ÇOK KIZGIN.",
["Ah! Kabloları kesmek elektrik akımını durduracak! Müthiş fikir be!"] = "AH! KABLOLARI KESMEK ELEKTRİK AKIMINI DURDURACAK! MÜTHİŞ FİKİR BE!",
["Ah! Kafanızın çalışmasını sevdim! O kamyonu yerine getirip kapıyı sökün."] = "AH! KAFANIZIN ÇALIŞMASINI SEVDİM! O KAMYONU YERİNE GETİRİP KAPIYI SÖKÜN.",
["Ah! Kafes boştu. Polislerin geri almasına mı izin verdiniz? Neyse. Eski usul sırtlayıp çıkarmanız gerekecek."] = "AH! KAFES BOŞTU. POLİSLERİN GERİ ALMASINA MI İZİN VERDİNİZ? NEYSE. ESKİ USUL SIRTLAYIP ÇIKARMANIZ GEREKECEK.",
["Ah! Kasa Dairesinde güvenlik tecridi var. Girmek için kontrol paneline sızın. Oralarda bir yerde."] = "AH! KASA DAİRESİNDE GÜVENLİK TECRİDİ VAR. GİRMEK İÇİN KONTROL PANELİNE SIZIN. ORALARDA BİR YERDE.",
["Ah! Kasa Dairesine girin, dostlar! Burada az kaldı!"] = "AH! KASA DAİRESİNE GİRİN, DOSTLAR! BURADA AZ KALDI!",
["Ah! Lanet olsun! Çok mu geç kaldık?"] = "AH! LANET OLSUN! ÇOK MU GEÇ KALDIK?",
["Ah! Murky'ler delirdi!"] = "AH! MURKY'LER DELİRDİ!",
["Ah! O adamlar çok yaklaşıyor!"] = "AH! O ADAMLAR ÇOK YAKLAŞIYOR!",
["Ah! O aptallar bombayı durdurdu. Oraya gidip yeniden başlatın."] = "AH! O APTALLAR BOMBAYI DURDURDU. ORAYA GİDİP YENİDEN BAŞLATIN.",
["Ah! O araç kaldırılmalı!"] = "AH! O ARAÇ KALDIRILMALI!",
["Ah! O bok yiyen amcıklar paramı çalıyor. Paramızı... pardon. Durdurun onları!"] = "AH! O BOK YİYEN AMCIKLAR PARAMI ÇALIYOR. PARAMIZI... PARDON. DURDURUN ONLARI!",
["Ah! O piç bana $20 borçluydu. Neyse."] = "AH! O PİÇ BANA $20 BORÇLUYDU. NEYSE.",
["Ah! O ses! Sanırım bir paket daha düştü, değil mi?"] = "AH! O SES! SANIRIM BİR PAKET DAHA DÜŞTÜ, DEĞİL Mİ?",
["Ah! Ona sessizce ulaşamıyoruz. Bakalım ne yapıyor. Bir dinleme cihazı yerleştirin."] = "AH! ONA SESSİZCE ULAŞAMIYORUZ. BAKALIM NE YAPIYOR. BİR DİNLEME CİHAZI YERLEŞTİRİN.",
["Ah! Polisler köprüyü çevirmiş! Tamam, biriniz kontrol odasına girip geri çevirsin. Öbür tarafa geçmeliyiz!"] = "AH! POLİSLER KÖPRÜYÜ ÇEVİRMİŞ! TAMAM, BİRİNİZ KONTROL ODASINA GİRİP GERİ ÇEVİRSİN. ÖBÜR TARAFA GEÇMELİYİZ!",
["Ah! Sakin olun demiştim! Federaller uyandı! Sunucu odasını bulup çıkın!"] = "AH! SAKİN OLUN DEMİŞTİM! FEDERALLER UYANDI! SUNUCU ODASINI BULUP ÇIKIN!",
["Ah! Siber güvenlikleri sıkı. Ayrı bir güvenlik duvarı kurmuşlar; büyük ihtimalle önemli bir bilgisayardan kontrol ediliyor. Xun Kang'ın toplantı odasında bir dizüstü bilgisayarı vardı. Aradığımız o mu, bakın."] = "AH! SİBER GÜVENLİKLERİ SIKI. AYRI BİR GÜVENLİK DUVARI KURMUŞLAR; BÜYÜK İHTİMALLE ÖNEMLİ BİR BİLGİSAYARDAN KONTROL EDİLİYOR. XUN KANG'IN TOPLANTI ODASINDA BİR DİZÜSTÜ BİLGİSAYARI VARDI. ARADIĞIMIZ O MU, BAKIN.",
["Ah! Umarım bu geceki şansınızın işareti değildir."] = "AH! UMARIM BU GECEKİ ŞANSINIZIN İŞARETİ DEĞİLDİR.",
["Ah! Vuruldum! Vurdular beni, vuruldum!"] = "AH! VURULDUM! VURDULAR BENİ, VURULDUM!",
["Ah! Yanlış vana sersemler. Baştan başlayalım."] = "AH! YANLIŞ VANA SERSEMLER. BAŞTAN BAŞLAYALIM.",
["Ah! Yanlış vana! Baştan!"] = "AH! YANLIŞ VANA! BAŞTAN!",
["Ah! Zımbırtı bozuldu. Yedek parça alıp onarın!"] = "AH! ZIMBIRTI BOZULDU. YEDEK PARÇA ALIP ONARIN!",
["Ah! İlk çanta! Kasa dairelerinin yakınında ganimeti bana yukarı iletecek dikey bir taşıma düzeneği bulacaksınız. Tamamen güvenli olacak!"] = "AH! İLK ÇANTA! KASA DAİRELERİNİN YAKININDA GANİMETİ BANA YUKARI İLETECEK DİKEY BİR TAŞIMA DÜZENEĞİ BULACAKSINIZ. TAMAMEN GÜVENLİ OLACAK!",
["Ah! İşte orada ama biraz bekleyin. O karolar basınca duyarlı; basmayın. Şu devre kutusuyla karşıya güvenli bir yol oluşturabilirsiniz."] = "AH! İŞTE ORADA AMA BİRAZ BEKLEYİN. O KAROLAR BASINCA DUYARLI; BASMAYIN. ŞU DEVRE KUTUSUYLA KARŞIYA GÜVENLİ BİR YOL OLUŞTURABİLİRSİNİZ.",
["Ah! İşte orada! Şimdi lütfen hava kilidinden çıkıp iç tesise girin!"] = "AH! İŞTE ORADA! ŞİMDİ LÜTFEN HAVA KİLİDİNDEN ÇIKIP İÇ TESİSE GİRİN!",
["Ah, C4 bağlanmış! Dikkat dostlar!"] = "AH, C4 BAĞLANMIŞ! DİKKAT DOSTLAR!",
["Ah, C4 bir kapının arkasında. Kesip açmak için şaloma falan bulabilir misiniz, bakın."] = "AH, C4 BİR KAPININ ARKASINDA. KESİP AÇMAK İÇİN ŞALOMA FALAN BULABİLİR MİSİNİZ, BAKIN.",
["Ah, HAYIR!"] = "AH, HAYIR!",
["Ah, Jiu Feng Kasa Dairesinin bu kadar sağlam olduğundan bahsetmedi. Matkapla delmeniz gerekecek. Dışarıya bir tane getirecek adamım hazır, hemen gelir!"] = "AH, JIU FENG KASA DAİRESİNİN BU KADAR SAĞLAM OLDUĞUNDAN BAHSETMEDİ. MATKAPLA DELMENİZ GEREKECEK. DIŞARIYA BİR TANE GETİRECEK ADAMIM HAZIR, HEMEN GELİR!",
["Ah, Kasa Dairesinin bu kadar ağır olmasını beklemiyordum. Matkap lazım. Dışarı çıkın, bir tane getirteyim."] = "AH, KASA DAİRESİNİN BU KADAR AĞIR OLMASINI BEKLEMİYORDUM. MATKAP LAZIM. DIŞARI ÇIKIN, BİR TANE GETİRTEYİM.",
["Ah, Vlad'ın verdiği planlardan sonra sistemi yenilemişler. Belki oralarda bir kullanım kılavuzu ya da şema bulursunuz."] = "AH, VLAD'IN VERDİĞİ PLANLARDAN SONRA SİSTEMİ YENİLEMİŞLER. BELKİ ORALARDA BİR KULLANIM KILAVUZU YA DA ŞEMA BULURSUNUZ.",
["Ah, acımıştır! Hayatta mı bari?"] = "AH, ACIMIŞTIR! HAYATTA MI BARİ?",
["Ah, alarm çaldı!"] = "AH, ALARM ÇALDI!",
["Ah, aman... Yumurta kırmak gibi olmayacak, ha?"] = "AH, AMAN... YUMURTA KIRMAK GİBİ OLMAYACAK, HA?",
["Ah, anladım. Bir taşla iki kuş. Düşünme şeklini beğendim Keegan."] = "AH, ANLADIM. BİR TAŞLA İKİ KUŞ. DÜŞÜNME ŞEKLİNİ BEĞENDİM KEEGAN.",
["Ah, anladım. Tabii, olur böyle şeyler. Tamam, bir dahakine önceden aramaya çalışın."] = "AH, ANLADIM. TABİİ, OLUR BÖYLE ŞEYLER. TAMAM, BİR DAHAKİNE ÖNCEDEN ARAMAYA ÇALIŞIN.",
["Ah, artık kapıyı matkapla delmeniz gerekecek."] = "AH, ARTIK KAPIYI MATKAPLA DELMENİZ GEREKECEK.",
["Ah, asansör bozuk! Ne aksilik! Dinleyin, yukarı çıkamadığım için benden aldıkları önemli bir şeyi aramalısınız. Metal bir evrak çantası. Geri almalıyım!"] = "AH, ASANSÖR BOZUK! NE AKSİLİK! DİNLEYİN, YUKARI ÇIKAMADIĞIM İÇİN BENDEN ALDIKLARI ÖNEMLİ BİR ŞEYİ ARAMALISINIZ. METAL BİR EVRAK ÇANTASI. GERİ ALMALIYIM!",
["Ah, avizeyi kullanmayı deneyelim. Onu tutan kablolardan birine biraz termit koyun."] = "AH, AVİZEYİ KULLANMAYI DENEYELİM. ONU TUTAN KABLOLARDAN BİRİNE BİRAZ TERMİT KOYUN.",
["Ah, az daha unutuyordum. İçeri girmek için şaloma kullanmalısınız."] = "AH, AZ DAHA UNUTUYORDUM. İÇERİ GİRMEK İÇİN ŞALOMA KULLANMALISINIZ.",
["Ah, bakın. O düğme ne yapıyor görün, olur mu? Belki bütün bina kendini imha eder? Pek sanmam."] = "AH, BAKIN. O DÜĞME NE YAPIYOR GÖRÜN, OLUR MU? BELKİ BÜTÜN BİNA KENDİNİ İMHA EDER? PEK SANMAM.",
["Ah, batırdınız. Size hediye yok."] = "AH, BATIRDINIZ. SİZE HEDİYE YOK.",
["Ah, başka güvenlik önlemi. Dışarı çıkmak için delmeniz gerekecek."] = "AH, BAŞKA GÜVENLİK ÖNLEMİ. DIŞARI ÇIKMAK İÇİN DELMENİZ GEREKECEK.",
["Ah, ben kostik soda diyorum."] = "AH, BEN KOSTİK SODA DİYORUM.",
["Ah, beni delirtiyorsunuz! Kimseyi kaybetme lüksümüz yoktu! İptal edin, güvenli eve dönün."] = "AH, BENİ DELİRTİYORSUNUZ! KİMSEYİ KAYBETME LÜKSÜMÜZ YOKTU! İPTAL EDİN, GÜVENLİ EVE DÖNÜN.",
["Ah, beni yanlamasına siksinler!"] = "AH, BENİ YANLAMASINA SİKSİNLER!",
["Ah, biliyorsunuz, o silahlardan birkaçını almadan gitmiyoruz. Bir şekilde dışarı çıkarmamız gerekiyor..."] = "AH, BİLİYORSUNUZ, O SİLAHLARDAN BİRKAÇINI ALMADAN GİTMİYORUZ. BİR ŞEKİLDE DIŞARI ÇIKARMAMIZ GEREKİYOR...",
["Ah, bir Jäger Mark II... İçindekileri yok etmeden açmak zordur."] = "AH, BİR JÄGER MARK II... İÇİNDEKİLERİ YOK ETMEDEN AÇMAK ZORDUR.",
["Ah, bir gerzek içeride, kapıyı da kilitlemiş. Dumanla çıkaralım. Gidip bir yerden biraz gaz \"ödünç alabilir\" misiniz bakın."] = "AH, BİR GERZEK İÇERİDE, KAPIYI DA KİLİTLEMİŞ. DUMANLA ÇIKARALIM. GİDİP BİR YERDEN BİRAZ GAZ \"ÖDÜNÇ ALABİLİR\" MİSİNİZ BAKIN.",
["Ah, bir güvenlik duvarı beni engelliyor. Diğer bilgisayarlardan birine gidip geçmeme yardım etmeye çalışın."] = "AH, BİR GÜVENLİK DUVARI BENİ ENGELLİYOR. DİĞER BİLGİSAYARLARDAN BİRİNE GİDİP GEÇMEME YARDIM ETMEYE ÇALIŞIN.",
["Ah, bir kasa! Ne ilginç!"] = "AH, BİR KASA! NE İLGİNÇ!",
["Ah, bir sürü bok! Temiz kaçış için o tareti indirmelisiniz."] = "AH, BİR SÜRÜ BOK! TEMİZ KAÇIŞ İÇİN O TARETİ İNDİRMELİSİNİZ.",
["Ah, bir sürü pislik! Sistem kırma işlemini durdurdular, yeniden başlatmanız gerekiyor."] = "AH, BİR SÜRÜ PİSLİK! SİSTEM KIRMA İŞLEMİNİ DURDURDULAR, YENİDEN BAŞLATMANIZ GEREKİYOR.",
["Ah, bir şekilde o şeyin içine girmeniz gerek. Buna pek hazırlıklı değildim."] = "AH, BİR ŞEKİLDE O ŞEYİN İÇİNE GİRMENİZ GEREK. BUNA PEK HAZIRLIKLI DEĞİLDİM.",
["Ah, bir şey fark etmiş olmalılar. PEOC'u arıyorlar. Beni hatta bağlayın. Bir de şans dileyin."] = "AH, BİR ŞEY FARK ETMİŞ OLMALILAR. PEOC'U ARIYORLAR. BENİ HATTA BAĞLAYIN. BİR DE ŞANS DİLEYİN.",
["Ah, bize GPS takmış olmalılar!"] = "AH, BİZE GPS TAKMIŞ OLMALILAR!",
["Ah, bize biraz da ot getirsenize kesinlikle. "] = "AH, BİZE BİRAZ DA OT GETİRSENİZE KESİNLİKLE. ",
["Ah, boktan zımbırtı!"] = "AH, BOKTAN ZIMBIRTI!",
["Ah, boş muymuş!? Aramaya devam edin!"] = "AH, BOŞ MUYMUŞ!? ARAMAYA DEVAM EDİN!",
["Ah, boş verin dostlar. Onun yerine sunucu odasının sistemini kırın. "] = "AH, BOŞ VERİN DOSTLAR. ONUN YERİNE SUNUCU ODASININ SİSTEMİNİ KIRIN. ",
["Ah, boş! Başkasını bulun."] = "AH, BOŞ! BAŞKASINI BULUN.",
["Ah, bravo! Yakıtımız dolu, gitmeye hazırız. Lütfen binin de çıkalım buradan. Güzel bir gündü."] = "AH, BRAVO! YAKITIMIZ DOLU, GİTMEYE HAZIRIZ. LÜTFEN BİNİN DE ÇIKALIM BURADAN. GÜZEL BİR GÜNDÜ.",
["Ah, bu FBI operasyonu, çıkış yok! Ateş ederek çıkmazsanız sizi indirecekler!"] = "AH, BU FBI OPERASYONU, ÇIKIŞ YOK! ATEŞ EDEREK ÇIKMAZSANIZ SİZİ İNDİRECEKLER!",
["Ah, bu bir FBI operasyonu. Çıkış yok; ateş ederek yol açmazsanız sizi indirecekler!"] = "AH, BU BİR FBI OPERASYONU. ÇIKIŞ YOK; ATEŞ EDEREK YOL AÇMAZSANIZ SİZİ İNDİRECEKLER!",
["Ah, bu ilginç olabilir!"] = "AH, BU İLGİNÇ OLABİLİR!",
["Ah, bu iyi değil. Orayı sessizce açmanın yolu yok, dostlar."] = "AH, BU İYİ DEĞİL. ORAYI SESSİZCE AÇMANIN YOLU YOK, DOSTLAR.",
["Ah, bu iyi olmadı!"] = "AH, BU İYİ OLMADI!",
["Ah, bu iş iyice boka sardı, millet!"] = "AH, BU İŞ İYİCE BOKA SARDI, MİLLET!",
["Ah, bu muhteşem olacak amına koyayım! Sıradaki parçayı getirin!"] = "AH, BU MUHTEŞEM OLACAK AMINA KOYAYIM! SIRADAKİ PARÇAYI GETİRİN!",
["Ah, bu ses tanıdık. Umarım kaza yapmaz."] = "AH, BU SES TANIDIK. UMARIM KAZA YAPMAZ.",
["Ah, bu sikikler bizi kazıklamaya çalışıyor!"] = "AH, BU SİKİKLER BİZİ KAZIKLAMAYA ÇALIŞIYOR!",
["Ah, bu utanç verici. Belki siz... Yok, karım beni asla affetmez."] = "AH, BU UTANÇ VERİCİ. BELKİ SİZ... YOK, KARIM BENİ ASLA AFFETMEZ.",
["Ah, bu çok kötü!"] = "AH, BU ÇOK KÖTÜ!",
["Ah, buna tünel girişi denir işte."] = "AH, BUNA TÜNEL GİRİŞİ DENİR İŞTE.",
["Ah, bundan kurtulmamızın imkânı yok çocuklar."] = "AH, BUNDAN KURTULMAMIZIN İMKÂNI YOK ÇOCUKLAR.",
["Ah, bunlar kararlı tiplerden."] = "AH, BUNLAR KARARLI TİPLERDEN.",
["Ah, bunu gizlice yapmalıydık. Bu işte tonla altın var."] = "AH, BUNU GİZLİCE YAPMALIYDIK. BU İŞTE TONLA ALTIN VAR.",
["Ah, bunu uzun zamandır görmemiştim. Konsol, anahtar üretici panel denen bir şeye bağlı. Sensörleri kapatmak istiyorsanız onu bulmalısınız. "] = "AH, BUNU UZUN ZAMANDIR GÖRMEMİŞTİM. KONSOL, ANAHTAR ÜRETİCİ PANEL DENEN BİR ŞEYE BAĞLI. SENSÖRLERİ KAPATMAK İSTİYORSANIZ ONU BULMALISINIZ. ",
["Ah, burada çok tanıdık yüz var, daha fazla eğlence için dönmüşler!"] = "AH, BURADA ÇOK TANIDIK YÜZ VAR, DAHA FAZLA EĞLENCE İÇİN DÖNMÜŞLER!",
["Ah, buraya bunun için geldik. Güzel ve parlak. Çelik halatla dışarı gönderin, tamam mı?"] = "AH, BURAYA BUNUN İÇİN GELDİK. GÜZEL VE PARLAK. ÇELİK HALATLA DIŞARI GÖNDERİN, TAMAM MI?",
["Ah, bütün bu kokainin giderden akıp gittiğini ve sizin hâlâ ağırdan aldığınızı görmek beni ülser edecek!"] = "AH, BÜTÜN BU KOKAİNİN GİDERDEN AKIP GİTTİĞİNİ VE SİZİN HÂLÂ AĞIRDAN ALDIĞINIZI GÖRMEK BENİ ÜLSER EDECEK!",
["Ah, dikkat dostlar! Tabii ya. Sadece eski, ilkel güvenliği olması gereken bankada lazer var. Bir bakayım... Evet... Çatıdan kapatabilmelisiniz!"] = "AH, DİKKAT DOSTLAR! TABİİ YA. SADECE ESKİ, İLKEL GÜVENLİĞİ OLMASI GEREKEN BANKADA LAZER VAR. BİR BAKAYIM... EVET... ÇATIDAN KAPATABİLMELİSİNİZ!",
["Ah, dikkat edin! Cloaker'lar artık sizi kelepçeleyebiliyor!"] = "AH, DİKKAT EDİN! CLOAKER'LAR ARTIK SİZİ KELEPÇELEYEBİLİYOR!",
["Ah, donunu ıslatma Bain! Alıcım var. Çok uzakta. Her şey yolunda. "] = "AH, DONUNU ISLATMA BAIN! ALICIM VAR. ÇOK UZAKTA. HER ŞEY YOLUNDA. ",
["Ah, doğru. Evet, tabii. Tamam, müsait olduğunda durum bildirsin."] = "AH, DOĞRU. EVET, TABİİ. TAMAM, MÜSAİT OLDUĞUNDA DURUM BİLDİRSİN.",
["Ah, evet. Bunu alıyorum."] = "AH, EVET. BUNU ALIYORUM.",
["Ah, evet. Durun. İçeri girmek için bu şaloma gerekecek."] = "AH, EVET. DURUN. İÇERİ GİRMEK İÇİN BU ŞALOMA GEREKECEK.",
["Ah, fark edildik. B planına geçiyoruz! Kontrolü ele alın, işleri halledin."] = "AH, FARK EDİLDİK. B PLANINA GEÇİYORUZ! KONTROLÜ ELE ALIN, İŞLERİ HALLEDİN.",
["Ah, fena bir hata yaptın amına koyayım..."] = "AH, FENA BİR HATA YAPTIN AMINA KOYAYIM...",
["Ah, gerzek amatörler, güvenlik kodlarını USB belleklerde tutuyorlar! Size demiştim, değil mi? Etrafa bakıp bulmaya çalışın."] = "AH, GERZEK AMATÖRLER, GÜVENLİK KODLARINI USB BELLEKLERDE TUTUYORLAR! SİZE DEMİŞTİM, DEĞİL Mİ? ETRAFA BAKIP BULMAYA ÇALIŞIN.",
["Ah, gerzekler, yanlış kod girdiniz!"] = "AH, GERZEKLER, YANLIŞ KOD GİRDİNİZ!",
["Ah, gidilecek bir yol daha. Kamyonun yanından ya da depodan geçin."] = "AH, GİDİLECEK BİR YOL DAHA. KAMYONUN YANINDAN YA DA DEPODAN GEÇİN.",
["Ah, gidip dedektörleri çalıştırdınız!"] = "AH, GİDİP DEDEKTÖRLERİ ÇALIŞTIRDINIZ!",
["Ah, gidip kokteylinizi bozmuşlar. Yeni bir tane karıştırmalısınız dostlar."] = "AH, GİDİP KOKTEYLİNİZİ BOZMUŞLAR. YENİ BİR TANE KARIŞTIRMALISINIZ DOSTLAR.",
["Ah, götüme kızgın demir soksunlar. Lanet palet kırıldı; para desteleri ihtiyar bir fahişenin donları gibi her yana saçıldı. Bulup çantalayın."] = "AH, GÖTÜME KIZGIN DEMİR SOKSUNLAR. LANET PALET KIRILDI; PARA DESTELERİ İHTİYAR BİR FAHİŞENİN DONLARI GİBİ HER YANA SAÇILDI. BULUP ÇANTALAYIN.",
["Ah, güvenlik kutularını çoktan halletmişsiniz. Önceden planlamak, hoşuma gitti."] = "AH, GÜVENLİK KUTULARINI ÇOKTAN HALLETMİŞSİNİZ. ÖNCEDEN PLANLAMAK, HOŞUMA GİTTİ.",
["Ah, güvenliği biraz artırıyorlar gibi. Daha fazla Murky'yle karşılaşmaya kesin hazır olun."] = "AH, GÜVENLİĞİ BİRAZ ARTIRIYORLAR GİBİ. DAHA FAZLA MURKY'YLE KARŞILAŞMAYA KESİN HAZIR OLUN.",
["Ah, güzel malım orada! Alın, alın!"] = "AH, GÜZEL MALIM ORADA! ALIN, ALIN!",
["Ah, güzel! Asansör geldi. Teli kapaktan geçirip kapıyla asansörün arasına bağlayın. Sonra asansör kablosunu vurun. O çekiş kapıları paramparça edecek."] = "AH, GÜZEL! ASANSÖR GELDİ. TELİ KAPAKTAN GEÇİRİP KAPIYLA ASANSÖRÜN ARASINA BAĞLAYIN. SONRA ASANSÖR KABLOSUNU VURUN. O ÇEKİŞ KAPILARI PARAMPARÇA EDECEK.",
["Ah, güzel! Vlad kulak misafiri olmayı sever!"] = "AH, GÜZEL! VLAD KULAK MİSAFİRİ OLMAYI SEVER!",
["Ah, güzel. PEOC'un girişi bu."] = "AH, GÜZEL. PEOC'UN GİRİŞİ BU.",
["Ah, güzel. Yakıt akıyor."] = "AH, GÜZEL. YAKIT AKIYOR.",
["Ah, güzelim mallarım orada! Güzel, güzel, çok güzel. Ah, bu Vlad'i çok mutlu ediyor. Ahh, alın, alın, alın, alın!"] = "AH, GÜZELİM MALLARIM ORADA! GÜZEL, GÜZEL, ÇOK GÜZEL. AH, BU VLAD'İ ÇOK MUTLU EDİYOR. AHH, ALIN, ALIN, ALIN, ALIN!",
["Ah, hadi ama! İndirin artık şunu. Saat başı para almıyorsunuz."] = "AH, HADİ AMA! İNDİRİN ARTIK ŞUNU. SAAT BAŞI PARA ALMIYORSUNUZ.",
["Ah, hadi!"] = "AH, HADİ!",
["Ah, haha. Bu, nasıl diyorsunuz: AŞIRIYA KAÇMAKTI. Bayıldım! Hapiste yıllarca bunu hayal ettim! Para sizin, hak ettiniz dostlarım."] = "AH, HAHA. BU, NASIL DİYORSUNUZ: AŞIRIYA KAÇMAKTI. BAYILDIM! HAPİSTE YILLARCA BUNU HAYAL ETTİM! PARA SİZİN, HAK ETTİNİZ DOSTLARIM.",
["Ah, harika. Şimdi bir bakalım."] = "AH, HARİKA. ŞİMDİ BİR BAKALIM.",
["Ah, hava kesinlikle daha iyi olabilirdi ama önemli değil. İçeri girin yeter."] = "AH, HAVA KESİNLİKLE DAHA İYİ OLABİLİRDİ AMA ÖNEMLİ DEĞİL. İÇERİ GİRİN YETER.",
["Ah, hava yastığının onu kurtaracağına eminim."] = "AH, HAVA YASTIĞININ ONU KURTARACAĞINA EMİNİM.",
["Ah, hayır hayır hayır hayır hayır! Arkamızda polisten trafik oluştu!"] = "AH, HAYIR HAYIR HAYIR HAYIR HAYIR! ARKAMIZDA POLİSTEN TRAFİK OLUŞTU!",
["Ah, hayır hayır hayır. Bir daha asla. Berbat bir aksan, güven bana."] = "AH, HAYIR HAYIR HAYIR. BİR DAHA ASLA. BERBAT BİR AKSAN, GÜVEN BANA.",
["Ah, hayır, polisler elektriği kesti. Binaların içinde devre kutusu bulup yeniden açın."] = "AH, HAYIR, POLİSLER ELEKTRİĞİ KESTİ. BİNALARIN İÇİNDE DEVRE KUTUSU BULUP YENİDEN AÇIN.",
["Ah, helikopter pistine ulaşamıyorum. Gidip geçidi uzatmalısınız. Kumandaları bulun."] = "AH, HELİKOPTER PİSTİNE ULAŞAMIYORUM. GİDİP GEÇİDİ UZATMALISINIZ. KUMANDALARI BULUN.",
["Ah, herifler matkabı durdurdu! Yeniden çalıştırın."] = "AH, HERİFLER MATKABI DURDURDU! YENİDEN ÇALIŞTIRIN.",
["Ah, hiçbir şey kolay olmuyor! Döner tablada kısa devre var. Tamir edebilir misiniz?"] = "AH, HİÇBİR ŞEY KOLAY OLMUYOR! DÖNER TABLADA KISA DEVRE VAR. TAMİR EDEBİLİR MİSİNİZ?",
["Ah, ihtiyar Locke'a kalp krizi geçirteceksiniz. Kıl payıydı."] = "AH, İHTİYAR LOCKE'A KALP KRİZİ GEÇİRTECEKSİNİZ. KIL PAYIYDI.",
["Ah, ilk kamyon boşaldı. Güzel manzara. Kasalar çok ağır değil, değil mi?"] = "AH, İLK KAMYON BOŞALDI. GÜZEL MANZARA. KASALAR ÇOK AĞIR DEĞİL, DEĞİL Mİ?",
["Ah, işim epey sıkıcı. Tekdüze. Makine gibi. Ama iyi kazandırıyor."] = "AH, İŞİM EPEY SIKICI. TEKDÜZE. MAKİNE GİBİ. AMA İYİ KAZANDIRIYOR.",
["Ah, işler karıştı. Dizüstü bilgisayara dönün. Belki ses okuyucusunu atlatabilirim."] = "AH, İŞLER KARIŞTI. DİZÜSTÜ BİLGİSAYARA DÖNÜN. BELKİ SES OKUYUCUSUNU ATLATABİLİRİM.",
["Ah, işte aradığımız şey. Güzel ve parlak. Alın ve gözünüz gibi koruyun!"] = "AH, İŞTE ARADIĞIMIZ ŞEY. GÜZEL VE PARLAK. ALIN VE GÖZÜNÜZ GİBİ KORUYUN!",
["Ah, işte burada. Tam önümde. 674523."] = "AH, İŞTE BURADA. TAM ÖNÜMDE. 674523.",
["Ah, işte böyle dostlar!"] = "AH, İŞTE BÖYLE DOSTLAR!",
["Ah, işte böyle. Bir kutu tuhaflık. Alıp sıradakine geçin."] = "AH, İŞTE BÖYLE. BİR KUTU TUHAFLIK. ALIP SIRADAKİNE GEÇİN.",
["Ah, işte gidiyor. Hahaha, güzel."] = "AH, İŞTE GİDİYOR. HAHAHA, GÜZEL.",
["Ah, kapalı. C4 de kullanamayız. O RFID okuyucuya bakın!"] = "AH, KAPALI. C4 DE KULLANAMAYIZ. O RFID OKUYUCUYA BAKIN!",
["Ah, kapı açıldı! Şimdi sürat ve şiddetle iç tesise ilerleyelim."] = "AH, KAPI AÇILDI! ŞİMDİ SÜRAT VE ŞİDDETLE İÇ TESİSE İLERLEYELİM.",
["Ah, kapı kilitli. Buluc şaraplarını güvende tutmayı seviyor. Açmak için şifreyi bulmanız gerekecek."] = "AH, KAPI KİLİTLİ. BULUC ŞARAPLARINI GÜVENDE TUTMAYI SEVİYOR. AÇMAK İÇİN ŞİFREYİ BULMANIZ GEREKECEK.",
["Ah, kasa dairesi bu millet. Bu sefer o kapıyı geçemeyiz. Ama altınlar... Öbür taraftaki altınlar! Neyse, bırakmak zorundayız."] = "AH, KASA DAİRESİ BU MİLLET. BU SEFER O KAPIYI GEÇEMEYİZ. AMA ALTINLAR... ÖBÜR TARAFTAKİ ALTINLAR! NEYSE, BIRAKMAK ZORUNDAYIZ.",
["Ah, kesin mi?"] = "AH, KESİN Mİ?",
["Ah, keçilerle geçen o gün... Ama buraya bir tane getirmek kimin fikriydi? Tuvalet eğitimi bile yok."] = "AH, KEÇİLERLE GEÇEN O GÜN... AMA BURAYA BİR TANE GETİRMEK KİMİN FİKRİYDİ? TUVALET EĞİTİMİ BİLE YOK.",
["Ah, kilitli tutacaklarını bilmeliydim. Kulüp binasındaki brifing odasında şifreye dair ipucu arayabilirsiniz."] = "AH, KİLİTLİ TUTACAKLARINI BİLMELİYDİM. KULÜP BİNASINDAKİ BRİFİNG ODASINDA ŞİFREYE DAİR İPUCU ARAYABİLİRSİNİZ.",
["Ah, kimya dersinde daha dikkatli olmalıymışım, değil mi? Merak etmeyin dostlarım... Yapa yapa çözeriz."] = "AH, KİMYA DERSİNDE DAHA DİKKATLİ OLMALIYMIŞIM, DEĞİL Mİ? MERAK ETMEYİN DOSTLARIM... YAPA YAPA ÇÖZERİZ.",
["Ah, kodu yanlış girdiniz sersemler! Sıfırlanması biraz sürecek."] = "AH, KODU YANLIŞ GİRDİNİZ SERSEMLER! SIFIRLANMASI BİRAZ SÜRECEK.",
["Ah, kulağımdan siksinler!"] = "AH, KULAĞIMDAN SİKSİNLER!",
["Ah, kusura bakma dostum, yanlış numarayı aramışım."] = "AH, KUSURA BAKMA DOSTUM, YANLIŞ NUMARAYI ARAMIŞIM.",
["Ah, kötü haberim var. Hava sahasını kapatıyorlar! Oradan hemen çıkmalısınız!"] = "AH, KÖTÜ HABERİM VAR. HAVA SAHASINI KAPATIYORLAR! ORADAN HEMEN ÇIKMALISINIZ!",
["Ah, kıymetlilerim orada! Acele edin, acele edin, alın onları!"] = "AH, KIYMETLİLERİM ORADA! ACELE EDİN, ACELE EDİN, ALIN ONLARI!",
["Ah, lanet bir sorun daha. Kontrol panosunu bulup sistemini kırın ki geçebilelim."] = "AH, LANET BİR SORUN DAHA. KONTROL PANOSUNU BULUP SİSTEMİNİ KIRIN Kİ GEÇEBİLELİM.",
["Ah, lanet olsun! Bağlantı koptu. Benim için elektriği tekrar açın."] = "AH, LANET OLSUN! BAĞLANTI KOPTU. BENİM İÇİN ELEKTRİĞİ TEKRAR AÇIN.",
["Ah, lanet olsun! Kalacak vakit yok... Çıkın oradan dostlar!"] = "AH, LANET OLSUN! KALACAK VAKİT YOK... ÇIKIN ORADAN DOSTLAR!",
["Ah, lanet olsun. Az kalmıştı ama şimdi acele etmemiz gerek. "] = "AH, LANET OLSUN. AZ KALMIŞTI AMA ŞİMDİ ACELE ETMEMİZ GEREK. ",
["Ah, lanet olsun. Bazı sorgu dosyaları kilitli. Onay gerekiyormuş... Hassiktir, bizzat müdürden. Bu köstebek her kimse sağlam bağlantıları var. Müdürün ofisine gidin!"] = "AH, LANET OLSUN. BAZI SORGU DOSYALARI KİLİTLİ. ONAY GEREKİYORMUŞ... HASSİKTİR, BİZZAT MÜDÜRDEN. BU KÖSTEBEK HER KİMSE SAĞLAM BAĞLANTILARI VAR. MÜDÜRÜN OFİSİNE GİDİN!",
["Ah, lanet olsun. O zaman arabasının anahtarlarını bulun! Umarım o hurda yığını çalışır!"] = "AH, LANET OLSUN. O ZAMAN ARABASININ ANAHTARLARINI BULUN! UMARIM O HURDA YIĞINI ÇALIŞIR!",
["Ah, lanet olsun. Tabii ki şifreli kilidi olacaktı. Belki kulüp binasının brifing odasında şifreyi öğrenmenin bir yolunu bulursunuz. Gidip bir bakın, olur mu?"] = "AH, LANET OLSUN. TABİİ Kİ ŞİFRELİ KİLİDİ OLACAKTI. BELKİ KULÜP BİNASININ BRİFİNG ODASINDA ŞİFREYİ ÖĞRENMENİN BİR YOLUNU BULURSUNUZ. GİDİP BİR BAKIN, OLUR MU?",
["Ah, lanet olsun. Yeni ultra hassas dedektörlerden takmışlar. Farklı bir yol izlemek gerek."] = "AH, LANET OLSUN. YENİ ULTRA HASSAS DEDEKTÖRLERDEN TAKMIŞLAR. FARKLI BİR YOL İZLEMEK GEREK.",
["Ah, lanet olsun..."] = "AH, LANET OLSUN...",
["Ah, lanet olsun... Boş çıktı. Aramaya ve taramaya devam edin."] = "AH, LANET OLSUN... BOŞ ÇIKTI. ARAMAYA VE TARAMAYA DEVAM EDİN.",
["Ah, lanet trafik. Az kaldı. Varınca tekneyi kullanabileceğine emin misin? "] = "AH, LANET TRAFİK. AZ KALDI. VARINCA TEKNEYİ KULLANABİLECEĞİNE EMİN MİSİN? ",
["Ah, lazerleri geçtiniz! O sistemi kapatmanın bir yolunu bulmalısınız."] = "AH, LAZERLERİ GEÇTİNİZ! O SİSTEMİ KAPATMANIN BİR YOLUNU BULMALISINIZ.",
["Ah, metal dedektörü var. Bu planda yoktu."] = "AH, METAL DEDEKTÖRÜ VAR. BU PLANDA YOKTU.",
["Ah, mükemmel. Şimdi hortumu pompaya götürün."] = "AH, MÜKEMMEL. ŞİMDİ HORTUMU POMPAYA GÖTÜRÜN.",
["Ah, ne düşüncelere dalabilirsin; zengin ve küfürbaz hâlinle, unutulmamış paranın o tuhaf, merak uyandıran yığını üzerinde. Böyle buyurdu Soyguncu."] = "AH, NE DÜŞÜNCELERE DALABİLİRSİN; ZENGİN VE KÜFÜRBAZ HÂLİNLE, UNUTULMAMIŞ PARANIN O TUHAF, MERAK UYANDIRAN YIĞINI ÜZERİNDE. BÖYLE BUYURDU SOYGUNCU.",
["Ah, ne düşündüğünüzü anladım! Azıcık su hasarı çok işe yarar!"] = "AH, NE DÜŞÜNDÜĞÜNÜZÜ ANLADIM! AZICIK SU HASARI ÇOK İŞE YARAR!",
["Ah, ne güzel bir şey bu, değil mi? Çıkarın şunu oradan, çabuk çabuk!"] = "AH, NE GÜZEL BİR ŞEY BU, DEĞİL Mİ? ÇIKARIN ŞUNU ORADAN, ÇABUK ÇABUK!",
["Ah, ne karmaşa çıkardık!"] = "AH, NE KARMAŞA ÇIKARDIK!",
["Ah, ne!? Millet, o maddelere dikkat etmelisiniz, size söyledim!"] = "AH, NE!? MİLLET, O MADDELERE DİKKAT ETMELİSİNİZ, SİZE SÖYLEDİM!",
["Ah, neredeyse gerçek savaş gibi! Orta Doğu'da gizli bir görev yaptığım zamanı anlattım mı size? Neyse, inmeden önce birkaç şey söylemeliyim. PEOC'a girmek için güvenlik Anahtar Kartı bulmanız gerekecek. Oraya matkapla ya da patlatarak girmemiz imkânsız. Bence aramaya Oval Ofisin yakınından başlamak en iyisi!"] = "AH, NEREDEYSE GERÇEK SAVAŞ GİBİ! ORTA DOĞU'DA GİZLİ BİR GÖREV YAPTIĞIM ZAMANI ANLATTIM MI SİZE? NEYSE, İNMEDEN ÖNCE BİRKAÇ ŞEY SÖYLEMELİYİM. PEOC'A GİRMEK İÇİN GÜVENLİK ANAHTAR KARTI BULMANIZ GEREKECEK. ORAYA MATKAPLA YA DA PATLATARAK GİRMEMİZ İMKÂNSIZ. BENCE ARAMAYA OVAL OFİSİN YAKININDAN BAŞLAMAK EN İYİSİ!",
["Ah, neyse... Siz klas tiplere benziyorsunuz!"] = "AH, NEYSE... SİZ KLAS TİPLERE BENZİYORSUNUZ!",
["Ah, o Kasa Dairesi kolay açılmayacak!"] = "AH, O KASA DAİRESİ KOLAY AÇILMAYACAK!",
["Ah, o SWAT helikopteri. Keskin nişancı bekleyin!"] = "AH, O SWAT HELİKOPTERİ. KESKİN NİŞANCI BEKLEYİN!",
["Ah, o bok parçası Vlad'e bulaştığına pişman olacak."] = "AH, O BOK PARÇASI VLAD'E BULAŞTIĞINA PİŞMAN OLACAK.",
["Ah, o kapıyı açmak biraz uğraştıracak. Belki top zımbırtısı yapar. Nişan aldırabiliyor musunuz bakın."] = "AH, O KAPIYI AÇMAK BİRAZ UĞRAŞTIRACAK. BELKİ TOP ZIMBIRTISI YAPAR. NİŞAN ALDIRABİLİYOR MUSUNUZ BAKIN.",
["Ah, o konteynerler iyice kapatılmış görünüyor. Vlad'ınkini de kilitledilerse kaynak şaloması gibi bir şeyle kesmeniz gerekecek."] = "AH, O KONTEYNERLER İYİCE KAPATILMIŞ GÖRÜNÜYOR. VLAD'INKİNİ DE KİLİTLEDİLERSE KAYNAK ŞALOMASI GİBİ BİR ŞEYLE KESMENİZ GEREKECEK.",
["Ah, o piçlerin bunu sizin için ortalıkta bırakması ne hoş."] = "AH, O PİÇLERİN BUNU SİZİN İÇİN ORTALIKTA BIRAKMASI NE HOŞ.",
["Ah, o silahları kapatmadan helikopterin inmesine imkân yok. Kontrol kutularını bulup bağlantılarını kesin."] = "AH, O SİLAHLARI KAPATMADAN HELİKOPTERİN İNMESİNE İMKÂN YOK. KONTROL KUTULARINI BULUP BAĞLANTILARINI KESİN.",
["Ah, o zımbırtı her neyse burada değil. Garrett henüz Kanıt Odasından almamış olmalı."] = "AH, O ZIMBIRTI HER NEYSE BURADA DEĞİL. GARRETT HENÜZ KANIT ODASINDAN ALMAMIŞ OLMALI.",
["Ah, o şeye bir şekilde girmelisiniz. Buna pek hazırlıklı değildim."] = "AH, O ŞEYE BİR ŞEKİLDE GİRMELİSİNİZ. BUNA PEK HAZIRLIKLI DEĞİLDİM.",
["Ah, o şeyi Buluc'un bacağında kullanın! Kökünden kesin."] = "AH, O ŞEYİ BULUC'UN BACAĞINDA KULLANIN! KÖKÜNDEN KESİN.",
["Ah, ona ne yapmışlar? Çabuk, bağlarını çözün!"] = "AH, ONA NE YAPMIŞLAR? ÇABUK, BAĞLARINI ÇÖZÜN!",
["Ah, onlardan biri. Etrafta ışıklara uyan bir şey bulabiliyor musunuz, bakın."] = "AH, ONLARDAN BİRİ. ETRAFTA IŞIKLARA UYAN BİR ŞEY BULABİLİYOR MUSUNUZ, BAKIN.",
["Ah, onlardan biri. Sıvı azot işi görürdü ama benden habersiz getirmediyseniz başka bir şey ayarlamamız gerekecek."] = "AH, ONLARDAN BİRİ. SIVI AZOT İŞİ GÖRÜRDÜ AMA BENDEN HABERSİZ GETİRMEDİYSENİZ BAŞKA BİR ŞEY AYARLAMAMIZ GEREKECEK.",
["Ah, orada da bir tane var."] = "AH, ORADA DA BİR TANE VAR.",
["Ah, oyalanırsanız böyle olur, dostlar! Rehineyi aldılar, eli boş dönmek zorundayız!"] = "AH, OYALANIRSANIZ BÖYLE OLUR, DOSTLAR! REHİNEYİ ALDILAR, ELİ BOŞ DÖNMEK ZORUNDAYIZ!",
["Ah, sabırsızlanıyorum! Hey millet, Buluc kurşunun benden geldiğini bilsin, tamam mı?"] = "AH, SABIRSIZLANIYORUM! HEY MİLLET, BULUC KURŞUNUN BENDEN GELDİĞİNİ BİLSİN, TAMAM MI?",
["Ah, sağlam vurdular onu."] = "AH, SAĞLAM VURDULAR ONU.",
["Ah, sevinçten uçuyorum. Hehehey! Harika bir iyilik yaptınız. O prenses teneke takmak zorunda kaldı. Hah! Hahaha! Vladimir Vladimirovich size borçlu!"] = "AH, SEVİNÇTEN UÇUYORUM. HEHEHEY! HARİKA BİR İYİLİK YAPTINIZ. O PRENSES TENEKE TAKMAK ZORUNDA KALDI. HAH! HAHAHA! VLADİMİR VLADİMİROVİCH SİZE BORÇLU!",
["Ah, siktir edin. Bu boku yapıyoruz."] = "AH, SİKTİR EDİN. BU BOKU YAPIYORUZ.",
["Ah, siktir!"] = "AH, SİKTİR!",
["Ah, siktir, Brown'ı suratından vurdular!"] = "AH, SİKTİR, BROWN'I SURATINDAN VURDULAR!",
["Ah, sivil kaybı! Dikkatli olun!"] = "AH, SİVİL KAYBI! DİKKATLİ OLUN!",
["Ah, sosyetik bir pislik içeride kahve molası veriyor. Kandırıp dışarı çıkarmalıyız."] = "AH, SOSYETİK BİR PİSLİK İÇERİDE KAHVE MOLASI VERİYOR. KANDIRIP DIŞARI ÇIKARMALIYIZ.",
["Ah, sus Boris. Orospu."] = "AH, SUS BORİS. OROSPU.",
["Ah, sıkışmış. Ulaşamıyorum. Kablolara ateş edin!"] = "AH, SIKIŞMIŞ. ULAŞAMIYORUM. KABLOLARA ATEŞ EDİN!",
["Ah, sıkıştı. Ateş edip düşürmemiz gerekecek."] = "AH, SIKIŞTI. ATEŞ EDİP DÜŞÜRMEMİZ GEREKECEK.",
["Ah, sıçayım!"] = "AH, SIÇAYIM!",
["Ah, sıçtık!"] = "AH, SIÇTIK!",
["Ah, sıçtık! Daha fazla lazer. Bağımsız bir sistem olmalı. Dizilişi izleyin. Şimdi alarm çalıştırmak istemeyiz."] = "AH, SIÇTIK! DAHA FAZLA LAZER. BAĞIMSIZ BİR SİSTEM OLMALI. DİZİLİŞİ İZLEYİN. ŞİMDİ ALARM ÇALIŞTIRMAK İSTEMEYİZ.",
["Ah, sıçtık! Işıklar söndü! Şalteri açın!"] = "AH, SIÇTIK! IŞIKLAR SÖNDÜ! ŞALTERİ AÇIN!",
["Ah, sıçtık! Sıçtık! Bir şey unuttum. Dinleyin, o Kasa Dairesinde kaset bulursanız onları da alın lütfen... Ben, şey... Belki sonra bir yerde yakarsınız, tamam mı?"] = "AH, SIÇTIK! SIÇTIK! BİR ŞEY UNUTTUM. DİNLEYİN, O KASA DAİRESİNDE KASET BULURSANIZ ONLARI DA ALIN LÜTFEN... BEN, ŞEY... BELKİ SONRA BİR YERDE YAKARSINIZ, TAMAM MI?",
["Ah, sıçtık, bunu beklemiyordum. Hiç mi kolay olmaz."] = "AH, SIÇTIK, BUNU BEKLEMİYORDUM. HİÇ Mİ KOLAY OLMAZ.",
["Ah, sıçtık, yine mi? Belki bir gece atıştırmalığı işe yarar. Yiyecek bulup Garrett'ın kapısının önüne koyun."] = "AH, SIÇTIK, YİNE Mİ? BELKİ BİR GECE ATIŞTIRMALIĞI İŞE YARAR. YİYECEK BULUP GARRETT'IN KAPISININ ÖNÜNE KOYUN.",
["Ah, sıçtık. Bu ifade dosyaları kilitli. Yalnızca Müdürün kendisinin onayıyla açılabilir. Hay sikeyim, bu en tepeye kadar gidiyor. Bir günlüğüne kral olmak isteyen var mı?"] = "AH, SIÇTIK. BU İFADE DOSYALARI KİLİTLİ. YALNIZCA MÜDÜRÜN KENDİSİNİN ONAYIYLA AÇILABİLİR. HAY SİKEYİM, BU EN TEPEYE KADAR GİDİYOR. BİR GÜNLÜĞÜNE KRAL OLMAK İSTEYEN VAR MI?",
["Ah, sıçtık. Burası tecrit durumuna geçti."] = "AH, SIÇTIK. BURASI TECRİT DURUMUNA GEÇTİ.",
["Ah, tabii ki bir Mark II olmalıydı."] = "AH, TABİİ Kİ BİR MARK II OLMALIYDI.",
["Ah, tamam dostlar. Güzel bir kazanç ama bence daha fazlasını alabilirdik!"] = "AH, TAMAM DOSTLAR. GÜZEL BİR KAZANÇ AMA BENCE DAHA FAZLASINI ALABİLİRDİK!",
["Ah, tamam! Burada güzel şeyler buluyorum!"] = "AH, TAMAM! BURADA GÜZEL ŞEYLER BULUYORUM!",
["Ah, tamam... Tuz, tuz ruhu. Daha ekleyin."] = "AH, TAMAM... TUZ, TUZ RUHU. DAHA EKLEYİN.",
["Ah, teşekkür ederim. Söylemeliyim ki hastanenin en şık giyimli hemşireleri siz ikinizsiniz."] = "AH, TEŞEKKÜR EDERİM. SÖYLEMELİYİM Kİ HASTANENİN EN ŞIK GİYİMLİ HEMŞİRELERİ SİZ İKİNİZSİNİZ.",
["Ah, teşekkürler!"] = "AH, TEŞEKKÜRLER!",
["Ah, tuz ruhunu seçiyorum."] = "AH, TUZ RUHUNU SEÇİYORUM.",
["Ah, tuş takımı çalışmıyor. Kapıyı patlatmanız gerek."] = "AH, TUŞ TAKIMI ÇALIŞMIYOR. KAPIYI PATLATMANIZ GEREK.",
["Ah, vinç kısa devre yaptı! Sigorta kutusunu tamir edin, çabuk! O kancalar sonsuza kadar dayanmaz!"] = "AH, VİNÇ KISA DEVRE YAPTI! SİGORTA KUTUSUNU TAMİR EDİN, ÇABUK! O KANCALAR SONSUZA KADAR DAYANMAZ!",
["Ah, yanlış yaptınız. Belki koruyucu tulum getirmek iyi fikir olurdu. Tepkimenin bitmesini bekleyip yeniden deneyin."] = "AH, YANLIŞ YAPTINIZ. BELKİ KORUYUCU TULUM GETİRMEK İYİ FİKİR OLURDU. TEPKİMENİN BİTMESİNİ BEKLEYİP YENİDEN DENEYİN.",
["Ah, yanlış yaptınız. Koruyucu tulum getirmek iyi fikir olabilirmiş. Tepkime bitene kadar bekleyip tekrar deneyin."] = "AH, YANLIŞ YAPTINIZ. KORUYUCU TULUM GETİRMEK İYİ FİKİR OLABİLİRMİŞ. TEPKİME BİTENE KADAR BEKLEYİP TEKRAR DENEYİN.",
["Ah, yapmayın lütfen!"] = "AH, YAPMAYIN LÜTFEN!",
["Ah, yapmayın! Bir sunucu eksik. Kayıtlara göre bilişime götürülmüş. Oraya gidip alın."] = "AH, YAPMAYIN! BİR SUNUCU EKSİK. KAYITLARA GÖRE BİLİŞİME GÖTÜRÜLMÜŞ. ORAYA GİDİP ALIN.",
["Ah, yine pompa. Lanet şeye daha fazla benzin lazım."] = "AH, YİNE POMPA. LANET ŞEYE DAHA FAZLA BENZİN LAZIM.",
["Ah, yine şu sızma işi. Daha fazla bilgisayar boku. Bilen birini bulun, kolunu mengeneye koyun, istediğiniz her şeyi yapar!"] = "AH, YİNE ŞU SIZMA İŞİ. DAHA FAZLA BİLGİSAYAR BOKU. BİLEN BİRİNİ BULUN, KOLUNU MENGENEYE KOYUN, İSTEDİĞİNİZ HER ŞEYİ YAPAR!",
["Ah, zımbırtı işletim sistemini güncellemeye çalışıyor. Ana bilgisayardan durdurun!"] = "AH, ZIMBIRTI İŞLETİM SİSTEMİNİ GÜNCELLEMEYE ÇALIŞIYOR. ANA BİLGİSAYARDAN DURDURUN!",
["Ah, çantaları yükleyin!"] = "AH, ÇANTALARI YÜKLEYİN!",
["Ah, özel bir şey yok. Saygılarımı sunmak için aradım."] = "AH, ÖZEL BİR ŞEY YOK. SAYGILARIMI SUNMAK İÇİN ARADIM.",
["Ah, şalteri bulup elektriği yeniden açın!"] = "AH, ŞALTERİ BULUP ELEKTRİĞİ YENİDEN AÇIN!",
["Ah, şanslısınız. Cömert hissediyorum."] = "AH, ŞANSLISINIZ. CÖMERT HİSSEDİYORUM.",
["Ah, şey... Sadece... Bilirsiniz, biraz mücevher falan."] = "AH, ŞEY... SADECE... BİLİRSİNİZ, BİRAZ MÜCEVHER FALAN.",
["Ah, şimdi de kelepçeleyen Cloaker'lar gönderiyorlar."] = "AH, ŞİMDİ DE KELEPÇELEYEN CLOAKER'LAR GÖNDERİYORLAR.",
["Ah, şimdi tanıdım. Payday palyaçoları bunlar!"] = "AH, ŞİMDİ TANIDIM. PAYDAY PALYAÇOLARI BUNLAR!",
["Ah, şimdi şu zımbırtının işini bitirmesini beklemeliyiz!"] = "AH, ŞİMDİ ŞU ZIMBIRTININ İŞİNİ BİTİRMESİNİ BEKLEMELİYİZ!",
["Ah, şu Garrett'ın ağzının ortasına bir kurşun yerleştirdiğinizi düşünün. Ama bu gece değil, dostlar. Uzun vadeli plan falan, değil mi?"] = "AH, ŞU GARRETT'IN AĞZININ ORTASINA BİR KURŞUN YERLEŞTİRDİĞİNİZİ DÜŞÜNÜN. AMA BU GECE DEĞİL, DOSTLAR. UZUN VADELİ PLAN FALAN, DEĞİL Mİ?",
["Ah, şu Mark II kasa modellerinden biri. İçindekileri yok etmeden patlatamayız."] = "AH, ŞU MARK II KASA MODELLERİNDEN BİRİ. İÇİNDEKİLERİ YOK ETMEDEN PATLATAMAYIZ.",
["Ah, şunu çıkarıp satabilsek... Ama açmakla yetinmemiz gerek. Anahtar o simgeler. Etrafta ipucu arayın, tamam mı?"] = "AH, ŞUNU ÇIKARIP SATABİLSEK... AMA AÇMAKLA YETİNMEMİZ GEREK. ANAHTAR O SİMGELER. ETRAFTA İPUCU ARAYIN, TAMAM MI?",
["Ah, şurada! 1965, 4,7 litre V8. O yıl üretilen en iyi ikinci şey, değil mi?"] = "AH, ŞURADA! 1965, 4,7 LİTRE V8. O YIL ÜRETİLEN EN İYİ İKİNCİ ŞEY, DEĞİL Mİ?",
["Ah, şurada! Bir Longfellow! 1965 model, 4.7 litre V8. Havalı yolculukları seversiniz, değil mi?"] = "AH, ŞURADA! BİR LONGFELLOW! 1965 MODEL, 4.7 LİTRE V8. HAVALI YOLCULUKLARI SEVERSİNİZ, DEĞİL Mİ?",
["Ah. Anladım. Hector o otobüste bubi tuzakları ‘olabileceğini’ söylemişti. "] = "AH. ANLADIM. HECTOR O OTOBÜSTE BUBİ TUZAKLARI ‘OLABİLECEĞİNİ’ SÖYLEMİŞTİ. ",
["Ah. Emin misiniz? Çünkü parayı biraz harcadım da."] = "AH. EMİN MİSİNİZ? ÇÜNKÜ PARAYI BİRAZ HARCADIM DA.",
["Ah. Şimdilik bırak onları. Kederimi içkiye boğuyorum. Yuri."] = "AH. ŞİMDİLİK BIRAK ONLARI. KEDERİMİ İÇKİYE BOĞUYORUM. YURİ.",
["Ah..."] = "AH...",
["Ah... Ee, evet. Sanırım bu... ihtiyatlı olur."] = "AH... EE, EVET. SANIRIM BU... İHTİYATLI OLUR.",
["Ah... Eh, bu herkesin dikkatini çekecek..."] = "AH... EH, BU HERKESİN DİKKATİNİ ÇEKECEK...",
["Ah... Evet. İyi fikir gibi. Sanırım."] = "AH... EVET. İYİ FİKİR GİBİ. SANIRIM.",
["Ah... Kahretsin!"] = "AH... KAHRETSİN!",
["Ah... Lanet olsun. Yakalandık. Yakalandık! Savaşma vakti!"] = "AH... LANET OLSUN. YAKALANDIK. YAKALANDIK! SAVAŞMA VAKTİ!",
["Ah... Seni moruk. Önce onu öldüreceğim."] = "AH... SENİ MORUK. ÖNCE ONU ÖLDÜRECEĞİM.",
["Ah... Tamam millet, helikoptere biraz yakıt gerekiyor. Deposu boş. Yaklaşık 10 - 15 dakika yerinizde kalmanız lazım. "] = "AH... TAMAM MİLLET, HELİKOPTERE BİRAZ YAKIT GEREKİYOR. DEPOSU BOŞ. YAKLAŞIK 10 - 15 DAKİKA YERİNİZDE KALMANIZ LAZIM. ",
["Ah... Yapamıyorum... Bakamıyorum bile... Hadi..."] = "AH... YAPAMIYORUM... BAKAMIYORUM BİLE... HADİ...",
["Ah... tamam. Her ihtimale karşı bölgeyi taramaları için birkaç adam yolluyoruz."] = "AH... TAMAM. HER İHTİMALE KARŞI BÖLGEYİ TARAMALARI İÇİN BİRKAÇ ADAM YOLLUYORUZ.",
["Aha! Gemi veri tabanı, haberleşme frekansları da var. Harika! Gereken bu. Şimdi Kaptanla telsizden görüşün."] = "AHA! GEMİ VERİ TABANI, HABERLEŞME FREKANSLARI DA VAR. HARİKA! GEREKEN BU. ŞİMDİ KAPTANLA TELSİZDEN GÖRÜŞÜN.",
["Aha! Moretta'nın iletişim frekansları. Bunları sonra kullanabiliriz ama dikkatinizi dağıtmayın."] = "AHA! MORETTA'NIN İLETİŞİM FREKANSLARI. BUNLARI SONRA KULLANABİLİRİZ AMA DİKKATİNİZİ DAĞITMAYIN.",
["Aha! İşte bu! Soğuk füzyon, tam burada. Ben bununla yakınlaşayım, siz de topuklayın."] = "AHA! İŞTE BU! SOĞUK FÜZYON, TAM BURADA. BEN BUNUNLA YAKINLAŞAYIM, SİZ DE TOPUKLAYIN.",
["Aha! İşte bu! Soğuk füzyon, tam burada. Uçağının anahtarları sizde, hatırladınız mı? Defolun oradan!"] = "AHA! İŞTE BU! SOĞUK FÜZYON, TAM BURADA. UÇAĞININ ANAHTARLARI SİZDE, HATIRLADINIZ MI? DEFOLUN ORADAN!",
["Aha, yük manifestosu. Konteynerler hakkında biraz bilgi her zaman işe yarar. Yine de genel bilgiler ama seçenekleri azaltıyor. İyi iş!"] = "AHA, YÜK MANİFESTOSU. KONTEYNERLER HAKKINDA BİRAZ BİLGİ HER ZAMAN İŞE YARAR. YİNE DE GENEL BİLGİLER AMA SEÇENEKLERİ AZALTIYOR. İYİ İŞ!",
["Ahaa, işte oradalar! O silahları güvene alın. Ne kadar çok alırsanız o kadar çok satarız."] = "AHAA, İŞTE ORADALAR! O SİLAHLARI GÜVENE ALIN. NE KADAR ÇOK ALIRSANIZ O KADAR ÇOK SATARIZ.",
["Ahaha, ne ışık gösterisi! Yol açıldı!"] = "AHAHA, NE IŞIK GÖSTERİSİ! YOL AÇILDI!",
["Ahh siktir dostum. Bu çocuklar çıldırıyor lan. Vuhuuuu!"] = "AHH SİKTİR DOSTUM. BU ÇOCUKLAR ÇILDIRIYOR LAN. VUHUUUU!",
["Ahh! DAHA FAZLA aptal! Kurye vinç parçalarını etrafa dağıtmış. Aramanız gerekecek dostlar."] = "AHH! DAHA FAZLA APTAL! KURYE VİNÇ PARÇALARINI ETRAFA DAĞITMIŞ. ARAMANIZ GEREKECEK DOSTLAR.",
["Ahh! O yaşlı göt herif geri dönüyor. Aferin. Paketlerimden birkaçını bulabilirseniz... Vlad çok minnettar olur."] = "AHH! O YAŞLI GÖT HERİF GERİ DÖNÜYOR. AFERİN. PAKETLERİMDEN BİRKAÇINI BULABİLİRSENİZ... VLAD ÇOK MİNNETTAR OLUR.",
["Ahh, açılan kasa dairesinden daha tatlı bir ses varsa o da ganimet çantalama sesidir. Kulaklarıma senfoni çalıyorsunuz!"] = "AHH, AÇILAN KASA DAİRESİNDEN DAHA TATLI BİR SES VARSA O DA GANİMET ÇANTALAMA SESİDİR. KULAKLARIMA SENFONİ ÇALIYORSUNUZ!",
["Ahh, bir Kasa Dairesi daha yağmalanmaya hazır!"] = "AHH, BİR KASA DAİRESİ DAHA YAĞMALANMAYA HAZIR!",
["Ahh, dinleyin. Kokain keçilerin içinde kaçırılıyor. Evet, keçiler. K. E. Ç. İ. Bir de kaçtılar. Hepsini bulun."] = "AHH, DİNLEYİN. KOKAİN KEÇİLERİN İÇİNDE KAÇIRILIYOR. EVET, KEÇİLER. K. E. Ç. İ. BİR DE KAÇTILAR. HEPSİNİ BULUN.",
["Ahh, servetin kokusunu buradan alıyorum! Çantaları doldurun!"] = "AHH, SERVETİN KOKUSUNU BURADAN ALIYORUM! ÇANTALARI DOLDURUN!",
["Ahhh! Kasa Dairesi. Sihrin kokusunu neredeyse (derin nefes alır) alıyorum!"] = "AHHH! KASA DAİRESİ. SİHRİN KOKUSUNU NEREDEYSE (DERİN NEFES ALIR) ALIYORUM!",
["Ahhh! LA! Yüzme havuzları, film yıldızları... Kokain alışkanlıkları, yıkılmış hayaller. Bayılıyorum."] = "AHHH! LA! YÜZME HAVUZLARI, FİLM YILDIZLARI... KOKAİN ALIŞKANLIKLARI, YIKILMIŞ HAYALLER. BAYILIYORUM.",
["Ahhh! O Kasa Dairesinde değerli bir prototip var. Sandıklardan birinin içinde, diğerlerinde değil. Bulmak için açın."] = "AHHH! O KASA DAİRESİNDE DEĞERLİ BİR PROTOTİP VAR. SANDIKLARDAN BİRİNİN İÇİNDE, DİĞERLERİNDE DEĞİL. BULMAK İÇİN AÇIN.",
["Ahhh! Sersem kurye çekme vincini unutmuş! Size trenle bir tane getirmeliyim. Başınızı dik tutun, tamam mı?"] = "AHHH! SERSEM KURYE ÇEKME VİNCİNİ UNUTMUŞ! SİZE TRENLE BİR TANE GETİRMELİYİM. BAŞINIZI DİK TUTUN, TAMAM MI?",
["Ahhh, arkadaşımdı. Eh, ne yapalım?"] = "AHHH, ARKADAŞIMDI. EH, NE YAPALIM?",
["Ahhh, kasalar. Benim küçük kıymetlilerim. Onları güvenle dışarı çıkarın. Bir taşıma aracı bulun."] = "AHHH, KASALAR. BENİM KÜÇÜK KIYMETLİLERİM. ONLARI GÜVENLE DIŞARI ÇIKARIN. BİR TAŞIMA ARACI BULUN.",
["Ahhh, kulaklarım beni yanıltmıyorsa bu, titanyum bir Kasa Dairesinin açılma sesi. Gayreti elden bırakmayın, dostlar!"] = "AHHH, KULAKLARIM BENİ YANILTMIYORSA BU, TİTANYUM BİR KASA DAİRESİNİN AÇILMA SESİ. GAYRETİ ELDEN BIRAKMAYIN, DOSTLAR!",
["Ahhh, metamfetamin hazır ama olduğu gibi çıkaramayız. Parçalamak gerek. Kırmaya başlayın, ekip!"] = "AHHH, METAMFETAMİN HAZIR AMA OLDUĞU GİBİ ÇIKARAMAYIZ. PARÇALAMAK GEREK. KIRMAYA BAŞLAYIN, EKİP!",
["Ahhh, son elf de öldü. Üzgün müyüm? Hayır, siktir edin elfi. Oyuncakları aldık, gitme vakti."] = "AHHH, SON ELF DE ÖLDÜ. ÜZGÜN MÜYÜM? HAYIR, SİKTİR EDİN ELFİ. OYUNCAKLARI ALDIK, GİTME VAKTİ.",
["Ahhh, şu paraya bakın. Tamam, çantaları doldurun, ekip!"] = "AHHH, ŞU PARAYA BAKIN. TAMAM, ÇANTALARI DOLDURUN, EKİP!",
["Ahır A - Giriş"] = "AHIR A - GİRİŞ",
["Ahır B - Güney Girişi"] = "AHIR B - GÜNEY GİRİŞİ",
["Ahır B - Kuzey Girişi"] = "AHIR B - KUZEY GİRİŞİ",
