["Alarm, kapının ikinci güvenlik özelliğini etkinleştirdi. İdari alandaki sistemi kırılmış bilgisayarı bulup manyetik kilidi açmak için kullan."] = "ALARM, KAPININ İKİNCİ GÜVENLİK ÖZELLİĞİNİ ETKİNLEŞTİRDİ. İDARİ ALANDAKİ SİSTEMİ KIRILMIŞ BİLGİSAYARI BULUP MANYETİK KİLİDİ AÇMAK İÇİN KULLAN.",
["Alarm, malzeme odalarının güvenlik sistemini etkinleştirdi. Kilitleri devre dışı bırakmak için güvenlik bilgisayarının sistemini kır."] = "ALARM, MALZEME ODALARININ GÜVENLİK SİSTEMİNİ ETKİNLEŞTİRDİ. KİLİTLERİ DEVRE DIŞI BIRAKMAK İÇİN GÜVENLİK BİLGİSAYARININ SİSTEMİNİ KIR.",
["Alarmları boş verin ekip, neredeyse bitti. The Dentist'in ganimetini kapıp çıkarın oradan. "] = "ALARMLARI BOŞ VERİN EKİP, NEREDEYSE BİTTİ. THE DENTIST'İN GANİMETİNİ KAPIP ÇIKARIN ORADAN. ",
["Alarmları boş verin millet. The Dentist'in ganimetini alın da işimiz bitsin."] = "ALARMLARI BOŞ VERİN MİLLET. THE DENTIST'İN GANİMETİNİ ALIN DA İŞİMİZ BİTSİN.",
["Alarmı boş verin, bizi bir an önce içeri sokun. Polisler üstümüze çökecek."] = "ALARMI BOŞ VERİN, BİZİ BİR AN ÖNCE İÇERİ SOKUN. POLİSLER ÜSTÜMÜZE ÇÖKECEK.",
["Alarmı devre dışı bırakarak iyi iş çıkardınız."] = "ALARMI DEVRE DIŞI BIRAKARAK İYİ İŞ ÇIKARDINIZ.",
["Alarmı devre dışı bırakmanız akıllıcaydı."] = "ALARMI DEVRE DIŞI BIRAKMANIZ AKILLICAYDI.",
["Alarmı kapatma işi ne durumda?"] = "ALARMI KAPATMA İŞİ NE DURUMDA?",
["Alarmı kapatın dostlar. "] = "ALARMI KAPATIN DOSTLAR. ",
["Alarmı kapatın! Geri sayıyor, 0'a ulaşınca işler fena karışacak."] = "ALARMI KAPATIN! GERİ SAYIYOR, 0'A ULAŞINCA İŞLER FENA KARIŞACAK.",
["Alarmı tetiklemeden cam kesmek için cam kesici."] = "ALARMI TETİKLEMEDEN CAM KESMEK İÇİN CAM KESİCİ.",
["Alarmı tetiklememek için güvenlik lazerlerini kapat."] = "ALARMI TETİKLEMEMEK İÇİN GÜVENLİK LAZERLERİNİ KAPAT.",
["Alarmı var, henüz açmayın. Önce alarmı kapatmamız gerek."] = "ALARMI VAR, HENÜZ AÇMAYIN. ÖNCE ALARMI KAPATMAMIZ GEREK.",
["Alarmı çaldırmadan müzayede evine girmeye çalış."] = "ALARMI ÇALDIRMADAN MÜZAYEDE EVİNE GİRMEYE ÇALIŞ.",
["Alarmı çaldırmalarını önlemek için çağrı cihazını yanıtla."] = "ALARMI ÇALDIRMALARINI ÖNLEMEK İÇİN ÇAĞRI CİHAZINI YANITLA.",
["Alarmı çaldırmamanız iyi oldu. Böyle devam edin."] = "ALARMI ÇALDIRMAMANIZ İYİ OLDU. BÖYLE DEVAM EDİN.",
["Alarmı çalın! Binada köstebekler var!"] = "ALARMI ÇALIN! BİNADA KÖSTEBEKLER VAR!",
["Alarmı çalıştırdılar! Çatışmaya hazırlanın!"] = "ALARMI ÇALIŞTIRDILAR! ÇATIŞMAYA HAZIRLANIN!",
["Alarmı çalıştırmalarını önlemek için kameraları yok et. Başlayınca hızlı davranmalısın."] = "ALARMI ÇALIŞTIRMALARINI ÖNLEMEK İÇİN KAMERALARI YOK ET. BAŞLAYINCA HIZLI DAVRANMALISIN.",
["Alarmı çalıştırıp kasa dairesini tecrit ettiler. Tecridi nasıl aşacağımızı öğrenebilmek için Mali İşler Direktörünü bul."] = "ALARMI ÇALIŞTIRIP KASA DAİRESİNİ TECRİT ETTİLER. TECRİDİ NASIL AŞACAĞIMIZI ÖĞRENEBİLMEK İÇİN MALİ İŞLER DİREKTÖRÜNÜ BUL.",
["Alaska Usulü İhanet"] = "ALASKA USULÜ İHANET",
["Alaska'da bir silah anlaşması için yardıma ihtiyacım var."] = "ALASKA'DA BİR SİLAH ANLAŞMASI İÇİN YARDIMA İHTİYACIM VAR.",
["Alaska'dan sonra bana güvenmek için pek nedeniniz olmadığını biliyorum. Ama sizi D.C.'den çıkarmak için zamanında kurabileceğimiz tek inandırıcı oyun oraya göndermekti. Bain'in eskiden güvenilir sandığı kişiler... dinliyordu. Şimdi de o yok. Bir şey olacağını biliyorduk ama ne zaman, ne olacağını değil. Sizi karanlıkta bırakmak benim kararımdı; Bain'in değil. Gerçekten ona ulaşabileceklerini hiç düşünmedim. Bakın, bunları duymanın berbat olduğunu biliyorum ama bıraktığım silahlarla çıktınız, değil mi? Bain için üzgünüm... halledeceğiz... ama önce sizi oradan çıkarmalıyız. Lütfen güvenin bana beyler, sizi kandırmıyorum. Kanıtlayacağıma söz veriyorum."] = "ALASKA'DAN SONRA BANA GÜVENMEK İÇİN PEK NEDENİNİZ OLMADIĞINI BİLİYORUM. AMA SİZİ D.C.'DEN ÇIKARMAK İÇİN ZAMANINDA KURABİLECEĞİMİZ TEK İNANDIRICI OYUN ORAYA GÖNDERMEKTİ. BAIN'İN ESKİDEN GÜVENİLİR SANDIĞI KİŞİLER... DİNLİYORDU. ŞİMDİ DE O YOK. BİR ŞEY OLACAĞINI BİLİYORDUK AMA NE ZAMAN, NE OLACAĞINI DEĞİL. SİZİ KARANLIKTA BIRAKMAK BENİM KARARIMDI; BAIN'İN DEĞİL. GERÇEKTEN ONA ULAŞABİLECEKLERİNİ HİÇ DÜŞÜNMEDİM. BAKIN, BUNLARI DUYMANIN BERBAT OLDUĞUNU BİLİYORUM AMA BIRAKTIĞIM SİLAHLARLA ÇIKTINIZ, DEĞİL Mİ? BAIN İÇİN ÜZGÜNÜM... HALLEDECEĞİZ... AMA ÖNCE SİZİ ORADAN ÇIKARMALIYIZ. LÜTFEN GÜVENİN BANA BEYLER, SİZİ KANDIRMIYORUM. KANITLAYACAĞIMA SÖZ VERİYORUM.",
["Alaskan Deal işinde OVERKILL veya üzeri zorlukta, polislerin tanktan gemiye yakıt akışını kesmesine izin verme."] = "ALASKAN DEAL İŞİNDE OVERKILL VEYA ÜZERİ ZORLUKTA, POLİSLERİN TANKTAN GEMİYE YAKIT AKIŞINI KESMESİNE İZİN VERME.",
["Alaskan Deal işinde bütün kardan adamları bulup başlarını ateş ederek kopar."] = "ALASKAN DEAL İŞİNDE BÜTÜN KARDAN ADAMLARI BULUP BAŞLARINI ATEŞ EDEREK KOPAR.",
