["Alaskan Deal işini bütün ekip üyeleri yalnızca Alev Makineleri kullanarak tamamla."] = "ALASKAN DEAL İŞİNİ BÜTÜN EKİP ÜYELERİ YALNIZCA ALEV MAKİNELERİ KULLANARAK TAMAMLA.",
["Alaskan Deal soygununu Death Sentence zorlukta One Down kuralı etkinken tamamla."] = "ALASKAN DEAL SOYGUNUNU DEATH SENTENCE ZORLUKTA ONE DOWN KURALI ETKİNKEN TAMAMLA.",
