["Aldım."] = "ALDIM.",
["Aldım. Artık Esteban'ın kime çalıştığını, onlara ne halt ettiğimi bulabilirim. Benim için aldığınız için sağ olun. Zahmetinizin karşılığını alacaksınız."] = "ALDIM. ARTIK ESTEBAN'IN KİME ÇALIŞTIĞINI, ONLARA NE HALT ETTİĞİMİ BULABİLİRİM. BENİM İÇİN ALDIĞINIZ İÇİN SAĞ OLUN. ZAHMETİNİZİN KARŞILIĞINI ALACAKSINIZ.",
["Aldım. Lütfen artık bittiğini söyle."] = "ALDIM. LÜTFEN ARTIK BİTTİĞİNİ SÖYLE.",
["Aldım. Sizin tarafa kaldırıyorum."] = "ALDIM. SİZİN TARAFA KALDIRIYORUM.",
["Aldım. Şimdi Esteban'ın kimin için çalıştığını çözebilirim. Bunu benim için aldığınızdan dolayı sağ olun."] = "ALDIM. ŞİMDİ ESTEBAN'IN KİMİN İÇİN ÇALIŞTIĞINI ÇÖZEBİLİRİM. BUNU BENİM İÇİN ALDIĞINIZDAN DOLAYI SAĞ OLUN.",
["Aldınız mı? Evrak çantasını? Güzel! Şimdi çıkalım oradan."] = "ALDINIZ MI? EVRAK ÇANTASINI? GÜZEL! ŞİMDİ ÇIKALIM ORADAN.",
["Aldınız mı? Neyse, bilmek istemiyorum. Beni takip edin yeter."] = "ALDINIZ MI? NEYSE, BİLMEK İSTEMİYORUM. BENİ TAKİP EDİN YETER.",
["Aldınız! Şimdi operasyon merkezine dönün!"] = "ALDINIZ! ŞİMDİ OPERASYON MERKEZİNE DÖNÜN!",
["Aldınız. Harika. Hepsini helikoptere taşıma vakti. Bile bekliyor, yola koyulun!"] = "ALDINIZ. HARİKA. HEPSİNİ HELİKOPTERE TAŞIMA VAKTİ. BILE BEKLİYOR, YOLA KOYULUN!",
["Aldınız. The Diamond'ı. O lanet Diamond'ı."] = "ALDINIZ. THE DIAMOND'I. O LANET DİAMOND'I.",
["Aldınız. Şimdi güvenle çıkarın!"] = "ALDINIZ. ŞİMDİ GÜVENLE ÇIKARIN!",
["Aldığımız kod cephanelikte çalışıyor. Girin içeri!"] = "ALDIĞIMIZ KOD CEPHANELİKTE ÇALIŞIYOR. GİRİN İÇERİ!",
