["Aldığın mühimmat, ekip arkadaşlarına da mühimmat kazandırır."] = "ALDIĞIN MÜHİMMAT, EKİP ARKADAŞLARINA DA MÜHİMMAT KAZANDIRIR.",
["Aldığın mühimmat, ekip arkadaşlarının da sağlığını yeniler."] = "ALDIĞIN MÜHİMMAT, EKİP ARKADAŞLARININ DA SAĞLIĞINI YENİLER.",
["Aldığınız Anahtar Kartıyla kapıyı açın. Ama içerideki herkesi çabucak indirmeye hazır olun."] = "ALDIĞINIZ ANAHTAR KARTIYLA KAPIYI AÇIN. AMA İÇERİDEKİ HERKESİ ÇABUCAK İNDİRMEYE HAZIR OLUN.",
["Aldığınız anahtar kartı hapishaneye erişim sağlamalı. Kapının yanındaki okuyucuda kullanın."] = "ALDIĞINIZ ANAHTAR KARTI HAPİSHANEYE ERİŞİM SAĞLAMALI. KAPININ YANINDAKİ OKUYUCUDA KULLANIN.",
["Aldığınız anahtar kartını kullanma vakti. Silahınızı hazır tutun ve kapının öte yanında kim varsa indirin."] = "ALDIĞINIZ ANAHTAR KARTINI KULLANMA VAKTİ. SİLAHINIZI HAZIR TUTUN VE KAPININ ÖTE YANINDA KİM VARSA İNDİRİN.",
["Aldığınız her şey çelik halatla dışarı gönderilmeli."] = "ALDIĞINIZ HER ŞEY ÇELİK HALATLA DIŞARI GÖNDERİLMELİ.",
