["Bak baba, yaptım. Artık uslu çocuk oldum mu?"] = "BAK BABA, YAPTIM. ARTIK USLU ÇOCUK OLDUM MU?",
["Bak ne diyeceğim, sizinle asla anlaşmayacaktık! Tamam mı? Biz, biz hepsini alacaktık..."] = "BAK NE DİYECEĞİM, SİZİNLE ASLA ANLAŞMAYACAKTIK! TAMAM MI? BİZ, BİZ HEPSİNİ ALACAKTIK...",
["Bak sen! Görünüşe göre Rainey, EPA'dakilere rüşvet vermek için şirket parasını kullanmış. Muhasebecisinden gelen bu e-posta FBI'ın çok ilgisini çeker bence."] = "BAK SEN! GÖRÜNÜŞE GÖRE RAİNEY, EPA'DAKİLERE RÜŞVET VERMEK İÇİN ŞİRKET PARASINI KULLANMIŞ. MUHASEBECİSİNDEN GELEN BU E-POSTA FBI'IN ÇOK İLGİSİNİ ÇEKER BENCE.",
["Bak sen! Rainey, muhasebecisine SERA'nın hesaplarından kara para geçirtmiş. Bu e-posta hissedarlara sızsa ne yazık olur. Çok yazık."] = "BAK SEN! RAİNEY, MUHASEBECİSİNE SERA'NIN HESAPLARINDAN KARA PARA GEÇİRTMİŞ. BU E-POSTA HİSSEDARLARA SIZSA NE YAZIK OLUR. ÇOK YAZIK.",
["Bak sen, kimler gelmiş? Sizi tanımıyorum. Sizi kimin gönderdiğini bilmiyorum. Gerçekten böyle mi oynamak istiyorsunuz?"] = "BAK SEN, KİMLER GELMİŞ? SİZİ TANIMIYORUM. SİZİ KİMİN GÖNDERDİĞİNİ BİLMİYORUM. GERÇEKTEN BÖYLE Mİ OYNAMAK İSTİYORSUNUZ?",
["Bak, ellerim yok! Ellerim yok!"] = "BAK, ELLERİM YOK! ELLERİM YOK!",
["Bak, krediyi ödersin ya da evi kaybedersin. Ciddiyim anne!"] = "BAK, KREDİYİ ÖDERSİN YA DA EVİ KAYBEDERSİN. CİDDİYİM ANNE!",
["Bak, rekabete sonuna kadar varım ama Rainey fazla ileri gitti. Kamyonlarımı patlatıyor. İşimi bozmak için o Esteban'ı tutuyor. Yeter artık."] = "BAK, REKABETE SONUNA KADAR VARIM AMA RAİNEY FAZLA İLERİ GİTTİ. KAMYONLARIMI PATLATIYOR. İŞİMİ BOZMAK İÇİN O ESTEBAN'I TUTUYOR. YETER ARTIK.",
["Bakalım Garrett şifreyi ortalıkta bırakacak kadar hödük müymüş."] = "BAKALIM GARRETT ŞİFREYİ ORTALIKTA BIRAKACAK KADAR HÖDÜK MÜYMÜŞ.",
["Bakalım bu vinç neler yapabiliyormuş!"] = "BAKALIM BU VİNÇ NELER YAPABİLİYORMUŞ!",
["Bakalım burada ne var."] = "BAKALIM BURADA NE VAR.",
["Bakalım burada ne varmış. Maretto'nun yük listesi. Artık hangi konteynerlerde ganimet olabileceğini biliyoruz. İyi buldunuz."] = "BAKALIM BURADA NE VARMIŞ. MARETTO'NUN YÜK LİSTESİ. ARTIK HANGİ KONTEYNERLERDE GANİMET OLABİLECEĞİNİ BİLİYORUZ. İYİ BULDUNUZ.",
["Bakalım burada ne varmış? Askerî planlar! Bunu araştırayım. "] = "BAKALIM BURADA NE VARMIŞ? ASKERÎ PLANLAR! BUNU ARAŞTIRAYIM. ",
["Bakalım burada ne varmış? Bilgisayar o olmalı. Sanırım yakınlarda."] = "BAKALIM BURADA NE VARMIŞ? BİLGİSAYAR O OLMALI. SANIRIM YAKINLARDA.",
["Bakalım ellerinde ne güzellikler var!"] = "BAKALIM ELLERİNDE NE GÜZELLİKLER VAR!",
["Bakalım yeni kelepçeleyen Cloaker'larımızla nasıl baş edeceksiniz..."] = "BAKALIM YENİ KELEPÇELEYEN CLOAKER'LARIMIZLA NASIL BAŞ EDECEKSİNİZ...",
["Bakalım, başka ne var. Burada her nesneyi deneyebilirsin. Ekipmanı alıp uyduğu bir şey bul yeter."] = "BAKALIM, BAŞKA NE VAR. BURADA HER NESNEYİ DENEYEBİLİRSİN. EKİPMANI ALIP UYDUĞU BİR ŞEY BUL YETER.",
["Bakalım. İşte! \"Gizli muhbir\"! Burnuma sıçan kokusu geldiğini biliyordum."] = "BAKALIM. İŞTE! \"GİZLİ MUHBİR\"! BURNUMA SIÇAN KOKUSU GELDİĞİNİ BİLİYORDUM.",
["Bakalım... Anahtar Kartı'nı panele takıp şalteri çalıştırın. Umarım büyük bir sürpriz beklemiyordur..."] = "BAKALIM... ANAHTAR KARTI'NI PANELE TAKIP ŞALTERİ ÇALIŞTIRIN. UMARIM BÜYÜK BİR SÜRPRİZ BEKLEMİYORDUR...",
["Bakalım... Caddeyi geçerseniz buradan çıkabilirsiniz."] = "BAKALIM... CADDEYİ GEÇERSENİZ BURADAN ÇIKABİLİRSİNİZ.",
["Bakalım... Gübre, mazot, kablo ve bir çeşit zamanlayıcı gerekecek. Bakın neler bulabileceksiniz."] = "BAKALIM... GÜBRE, MAZOT, KABLO VE BİR ÇEŞİT ZAMANLAYICI GEREKECEK. BAKIN NELER BULABİLECEKSİNİZ.",
["Bakayım, bir, iki. Evet, hepsi burada! Şimdi lütfen halatları kullanıp yukarı, yanıma gelin."] = "BAKAYIM, BİR, İKİ. EVET, HEPSİ BURADA! ŞİMDİ LÜTFEN HALATLARI KULLANIP YUKARI, YANIMA GELİN.",
["Bakiye"] = "BAKİYE",
["Bakkala gir."] = "BAKKALA GİR.",
["Bakım Girişi"] = "BAKIM GİRİŞİ",
["Bakım Kulübesi"] = "BAKIM KULÜBESİ",
["Bakım tünellerinde bir sürü oda var. Hepsine bakın."] = "BAKIM TÜNELLERİNDE BİR SÜRÜ ODA VAR. HEPSİNE BAKIN.",
["Bakım tünellerinde birkaç oda var. Hepsine baktınız mı?"] = "BAKIM TÜNELLERİNDE BİRKAÇ ODA VAR. HEPSİNE BAKTINIZ MI?",
["Bakım tünellerindeki bütün odalara baktınız mı?"] = "BAKIM TÜNELLERİNDEKİ BÜTÜN ODALARA BAKTINIZ MI?",
["Bakım tünellerine bakmaya değer olabilir."] = "BAKIM TÜNELLERİNE BAKMAYA DEĞER OLABİLİR.",
["Bakın başrahibe, ya $300 ödersiniz ya da bacaklarınızı kırarız!"] = "BAKIN BAŞRAHİBE, YA $300 ÖDERSİNİZ YA DA BACAKLARINIZI KIRARIZ!",
["Bakın dostlarım, bu iş olacaksa bazen dediğimi yapmalısınız. Ben de o sikik balyaları bulun diyorum!!"] = "BAKIN DOSTLARIM, BU İŞ OLACAKSA BAZEN DEDİĞİMİ YAPMALISINIZ. BEN DE O SİKİK BALYALARI BULUN DİYORUM!!",
["Bakın millet! Kendinize gelin de polislerden önce o çantaları güvene alın. Sizi alacak tekne yolda."] = "BAKIN MİLLET! KENDİNİZE GELİN DE POLİSLERDEN ÖNCE O ÇANTALARI GÜVENE ALIN. SİZİ ALACAK TEKNE YOLDA.",
["Bakın ne diyeceğim: Sizinle anlaşmaya hiç niyetimiz yoktu! Hepsini alıyoruz!"] = "BAKIN NE DİYECEĞİM: SİZİNLE ANLAŞMAYA HİÇ NİYETİMİZ YOKTU! HEPSİNİ ALIYORUZ!",
["Bakın ne iyi adamım. Bir bağlantıma sizin için fazladan Ceset Torbaları saklattım."] = "BAKIN NE İYİ ADAMIM. BİR BAĞLANTIMA SİZİN İÇİN FAZLADAN CESET TORBALARI SAKLATTIM.",
["Bakın porsuk çalılardan ne çıkarmış! Neredeyse gelmeyecek sanmıştım! Arabanız geldi dostlar!"] = "BAKIN PORSUK ÇALILARDAN NE ÇIKARMIŞ! NEREDEYSE GELMEYECEK SANMIŞTIM! ARABANIZ GELDİ DOSTLAR!",
["Bakın! Hediye! Gidip alın!"] = "BAKIN! HEDİYE! GİDİP ALIN!",
["Bakın, Vlad'ın çatlak olduğunu biliyorum. Ama çok bağlantısı var. İleride bizi büyük işlere götürebileceği konusunda içimden iyi bir his geçiyor. "] = "BAKIN, VLAD'IN ÇATLAK OLDUĞUNU BİLİYORUM. AMA ÇOK BAĞLANTISI VAR. İLERİDE BİZİ BÜYÜK İŞLERE GÖTÜREBİLECEĞİ KONUSUNDA İÇİMDEN İYİ BİR HİS GEÇİYOR. ",
["Bakın, Vlad'ın çatlak olduğunu biliyorum. Ama çok bağlantısı var. İleride bizi büyük işlere götürebileceği konusunda içimden iyi bir his geçiyor. Bu iyi bir başlangıç. Ortalık kızışana kadar soğukkanlı kalın yeter."] = "BAKIN, VLAD'IN ÇATLAK OLDUĞUNU BİLİYORUM. AMA ÇOK BAĞLANTISI VAR. İLERİDE BİZİ BÜYÜK İŞLERE GÖTÜREBİLECEĞİ KONUSUNDA İÇİMDEN İYİ BİR HİS GEÇİYOR. BU İYİ BİR BAŞLANGIÇ. ORTALIK KIZIŞANA KADAR SOĞUKKANLI KALIN YETER.",
["Bakın, ateş etmeye başladıklarında o kapılar dayanmayacak."] = "BAKIN, ATEŞ ETMEYE BAŞLADIKLARINDA O KAPILAR DAYANMAYACAK.",
["Bakın, her şeyi söylemem mi gerekiyor? Termal macunla ızgarayı yakıp geçin."] = "BAKIN, HER ŞEYİ SÖYLEMEM Mİ GEREKİYOR? TERMAL MACUNLA IZGARAYI YAKIP GEÇİN.",
["Bakın, işte orada!"] = "BAKIN, İŞTE ORADA!",
["Bakın, pencerede bir kız var."] = "BAKIN, PENCEREDE BİR KIZ VAR.",
["Bakın, yukarıdaki iskelede! Bir keçi daha. Ama durun! Merdivene elektrik verilmiş gibi. Elektriği kesin!"] = "BAKIN, YUKARIDAKİ İSKELEDE! BİR KEÇİ DAHA. AMA DURUN! MERDİVENE ELEKTRİK VERİLMİŞ GİBİ. ELEKTRİĞİ KESİN!",
